// Loads and decodes the pre-built binaries from /data (see scripts/build).
const BASE = import.meta.env.BASE_URL + 'data/';

async function fetchBytes(name, onBytes) {
  const res = await fetch(BASE + name);
  if (!res.ok) throw new Error(`${name}: HTTP ${res.status}`);
  const reader = res.body.getReader();
  const chunks = [];
  let len = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value); len += value.length;
    onBytes?.(value.length);
  }
  const all = new Uint8Array(len);
  let o = 0;
  for (const c of chunks) { all.set(c, o); o += c.length; }
  return all;
}

async function gunzip(bytes) {
  // Some static hosts transparently decode .gz: only inflate when the gzip magic is still there.
  if (bytes[0] !== 0x1f || bytes[1] !== 0x8b) return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  return new Response(stream).arrayBuffer();
}

export async function loadBinary(name, onBytes) {
  return gunzip(await fetchBytes(name, onBytes));
}

export async function loadJSON(name) {
  const res = await fetch(BASE + name);
  if (!res.ok) throw new Error(`${name}: HTTP ${res.status}`);
  return res.json();
}

/** Sequential reader that copies slices into aligned typed arrays. */
class Reader {
  constructor(buf) { this.buf = buf; this.o = 0; }
  take(Type, n) {
    const bytes = n * Type.BYTES_PER_ELEMENT;
    const out = new Type(this.buf.slice(this.o, this.o + bytes));
    this.o += bytes;
    return out;
  }
}

export function parseBuildings(geomBuf, attrBuf) {
  const r = new Reader(geomBuf);
  const head = r.take(Int32Array, 8);
  const n = head[1], nRings = head[2], nVerts = head[3], nChunks = head[4];
  const geom = {
    n, nRings, nVerts, nChunks,
    chunkBounds: r.take(Int32Array, nChunks + 1),
    ringCount: r.take(Uint8Array, n),
    ringLen: r.take(Uint16Array, nRings),
    origin: r.take(Int32Array, n * 2),
    xy: r.take(Uint16Array, nVerts * 2),
  };
  const a = new Reader(attrBuf);
  const attr = {
    z: a.take(Float32Array, n), h: a.take(Float32Array, n),
    tc: a.take(Int16Array, n), tl: a.take(Int16Array, n),
    s: a.take(Float32Array, n), arr: a.take(Uint8Array, n), flags: a.take(Uint8Array, n), year: a.take(Uint16Array, n),
  };
  return { geom, attr };
}

export function parseStats(buf, nl) {
  const r = new Reader(buf);
  return {
    buildings: r.take(Uint32Array, 2 * 21 * nl),     // [mode][arr 0=all][cm]
    area: r.take(Float32Array, 2 * 3 * nl),          // [mode][land|open|built][cm]
    areaArr: r.take(Float32Array, 2 * 21 * nl),      // [mode][arr][cm]
    dmax: r.take(Float32Array, 2 * 101),             // [mode][dm]
    nl,
  };
}

/** Loads everything needed before the first frame. Progress is reported 0..1. */
export async function loadCore(onProgress) {
  const files = ['flood_T.bin.gz', 'ground.bin.gz', 'river_s.bin.gz', 'masks.bin.gz', 'buildings_geom.bin.gz', 'buildings_attr.bin.gz', 'stats.bin.gz'];
  const sizes = {};
  let got = 0, total = 1;
  // HEAD is not reliably supported by every static host, so progress is approximate: 14 MB total.
  total = 14.0e6;
  const tick = (n) => { got += n; onProgress?.(Math.min(0.99, got / total)); };
  const [meta, stations, ...bins] = await Promise.all([
    loadJSON('meta.json'), loadJSON('stations.json'),
    ...files.map((f) => loadBinary(f, tick)),
  ]);
  const [T, ground, riverS, masks, bg, ba, st] = bins;
  const g = meta.grid;
  return {
    meta, stations,
    T: new Int16Array(T), ground: new Uint16Array(ground), riverS: new Float32Array(riverS),
    masks: new Uint8Array(masks),
    buildings: parseBuildings(bg, ba),
    stats: parseStats(st, meta.nl),
    sizes, grid: g,
  };
}

export async function loadPPRI() {
  const [a, b] = await Promise.all([loadBinary('ppri_a.bin.gz'), loadBinary('ppri_b.bin.gz')]);
  return { a: new Uint8Array(a), b: new Uint8Array(b) };
}

