// Constants, historic floods and visual themes.

export const Y_REF = 25.0;            // scene y = (NGF altitude - Y_REF) * exaggeration
export const MAX_LEVEL = 10.0;        // slider range (m on the Pont d'Austerlitz gauge)

export const HISTORIC = [
  { year: 2018, level: 5.84, key: 'f2018' },
  { year: 2016, level: 6.10, key: 'f2016' },
  { year: 1955, level: 7.12, key: 'f1955' },
  { year: 1910, level: 8.62, key: 'f1910' },
