export const terrainFS = /* glsl */ `
${COMMON}
uniform vec3 uStreetCol; uniform vec3 uParkCol; uniform vec3 uCanalCol; uniform vec3 uContourCol;
uniform float uContour;
varying vec2 vUV;
varying vec3 vWorld;
varying float vNGF;
#ifdef PICK
void main() { if (texture2D(tMasks, vUV).a < 0.5) discard; gl_FragColor = vec4(0.0); }
#else
void main() {
  vec4 m = texture2D(tMasks, vUV);
  if (m.a < 0.5) discard;
  vec2 cell = 1.0 / uGridSize;
  float hE = groundAt(vUV + vec2(cell.x, 0.0)), hW = groundAt(vUV - vec2(cell.x, 0.0));
  float hS = groundAt(vUV + vec2(0.0, cell.y)), hN = groundAt(vUV - vec2(0.0, cell.y));
  vec3 n = normalize(vec3(-(hE - hW) * uExag, 10.0, -(hS - hN) * uExag));

  vec3 base = mix(uStreetCol, uParkCol, m.g * 0.92);
  base = mix(base, uCanalCol, m.b);
  base *= 1.0 - 0.40 * m.r;
  float hypso = smoothstep(27.0, 80.0, vNGF);
  base = mix(base, base * 1.45 + vec3(0.012, 0.016, 0.02), hypso);

  float ndl = max(dot(n, normalize(uSunDir)), 0.0);
  vec3 light = mix(uAmbGround, uAmbSky, n.y * 0.5 + 0.5) * uAmbient + uSunCol * ndl * 0.7;
  vec3 c = base * light;

  // 1 m / 5 m altitude contours: they show the flood plain at a glance
  float fw = max(fwidth(vNGF), 1e-4);
  float dist1 = abs(fract(vNGF - 0.5) - 0.5) / fw;
  float dist5 = abs(fract(vNGF / 5.0 - 0.5) - 0.5) * 5.0 / fw;
  float fade = 1.0 - smoothstep(0.10, 0.35, fw);
  float lines = (1.0 - clamp(dist1, 0.0, 1.0)) * 0.35 + (1.0 - clamp(dist5, 0.0, 1.0)) * 0.55;
  lines *= fade * (1.0 - smoothstep(38.0, 48.0, vNGF));
  c = mix(c, uContourCol, clamp(lines * uContour, 0.0, 0.8));

  c = applyFog(c, distance(cameraPosition, vWorld));
  gl_FragColor = vec4(toDisplay(c), 1.0);
}
#endif`;

// ----------------------------------------------------------------------------------- water
export const waterVS = /* glsl */ `
${COMMON}
varying vec2 vUV;
varying vec3 vWorld;
varying float vSurf;
void main() {
  vec2 xz = position.xz;
  vUV = xzToUV(xz);
  float s = riverSAt(vUV);
  float surf = surfaceZ(uLevel, s);
  vSurf = surf;
  vec3 p = vec3(xz.x, sceneY(surf) + 0.05, xz.y);
  vWorld = p;
  gl_Position = projectionMatrix * viewMatrix * vec4(p, 1.0);
}`;

export const waterFS = /* glsl */ `
${COMMON}
uniform vec3 uShallow; uniform vec3 uDeep; uniform vec3 uRiver; uniform vec3 uRiverDeep; uniform vec3 uSkyRefl; uniform float uGlow;
uniform vec3 uHorizon;
varying vec2 vUV;
varying vec3 vWorld;
varying float vSurf;

float wave(vec2 p, float t) {
  return vnoise(p + vec2(t * 0.30, t * 0.11)) * 0.50 + vnoise(p * 2.13 - vec2(t * 0.21, -t * 0.27)) * 0.28 + vnoise(p * 4.7 + vec2(-t * 0.35, t * 0.18)) * 0.14;
}
void main() {
  vec4 m = texture2D(tMasks, vUV);
  float dom = smoothstep(0.30, 0.65, m.a);
  float g = groundAt(vUV);
  float depth = vSurf - g;
  float tF = floodTAt(vUV);

  float aaT = fwidth(tF) + 0.0015;
  float connected = clamp((uLevel - tF) / aaT * 0.5 + 0.5, 0.0, 1.0);
  float fm = mix(connected, 1.0, uMode);
  float aaD = fwidth(depth) + 0.0015;
  float dm = clamp(depth / aaD * 0.5 + 0.5, 0.0, 1.0);
  float mask = fm * dm * dom;
  if (mask < 0.01) discard;

  float isRiver = 1.0 - smoothstep(-0.25, 0.15, tF);
  float dist = distance(cameraPosition, vWorld);

  // procedural ripples, faded with distance to avoid shimmering
  float amp = 1.0 / (1.0 + dist * 0.0012);
  vec2 p = vWorld.xz * 0.30;
  float e = 0.12;
  float w0 = wave(p, uTime), wx = wave(p + vec2(e, 0.0), uTime), wz = wave(p + vec2(0.0, e), uTime);
  vec3 N = normalize(vec3((w0 - wx) / e * 0.35 * amp, 1.0, (w0 - wz) / e * 0.35 * amp));
  vec3 V = normalize(cameraPosition - vWorld);
  vec3 Ld = normalize(uSunDir);

  float dd = 1.0 - exp(-max(depth, 0.0) * 0.35);
  vec3 floodBody = mix(uShallow, uDeep, dd);
  vec3 riverBody = mix(uRiver, uRiverDeep, 0.5 + 0.5 * vnoise(vWorld.xz * 0.02 + uTime * 0.02));
  vec3 body = mix(floodBody, riverBody, isRiver);

  float fres = 0.06 + 0.94 * pow(1.0 - max(dot(N, V), 0.0), 4.0);
  vec3 refl = mix(uHorizon, uSkyRefl, clamp(N.y * 0.5 + reflect(-V, N).y, 0.0, 1.0));
  float spec = pow(max(dot(reflect(-Ld, N), V), 0.0), 120.0) * 1.8;
  vec3 c = mix(body, refl, fres * (0.55 + 0.25 * isRiver)) + uSunCol * spec;

  // streets and open ground light up where the water lies on them
  float open = 1.0 - m.r;
  c += uShallow * uGlow * (0.30 * open + 0.06) * (1.0 - isRiver);
  // flood front
  float rim = (1.0 - smoothstep(0.0, 0.55, depth)) * (1.0 - isRiver);
  float flicker = 0.75 + 0.25 * sin(uTime * 2.0 + vWorld.x * 0.05 + vWorld.z * 0.07);
  c += vec3(0.65, 0.95, 1.0) * rim * uGlow * 0.55 * flicker;

  c = applyFog(c, dist);
  float alpha = mix(mix(0.62, 0.93, dd), 0.97, isRiver) * mask;
  alpha = max(alpha, rim * 0.9 * mask);
  gl_FragColor = vec4(toDisplay(c), alpha);
}`;

// ----------------------------------------------------------------------------------- buildings
export const buildingVS = /* glsl */ `
${COMMON}
uniform sampler2D tBldA; // z, height, connected threshold (m), river abscissa (km)
uniform sampler2D tBldB; // level-only threshold (m), arrondissement, flags, year
uniform vec2 uBldTex;
varying vec3 vWorld;
flat varying float vId;
flat varying float vGround;
flat varying float vHeight;
flat varying float vSurf;
flat varying float vFlood;
flat varying float vDepth;
flat varying float vArr;
varying float vNGF;
void main() {
  float aId = position.y;
  float top = mod(aId, 2.0);
  float id = floor(aId * 0.5);
  ivec2 tc = ivec2(int(mod(id, uBldTex.x)), int(floor(id / uBldTex.x)));
  vec4 A = texelFetch(tBldA, tc, 0);
  vec4 B = texelFetch(tBldB, tc, 0);
  float z = A.x, h = A.y;
  float surf = surfaceZ(uLevel, A.w);
  float tB = mix(A.z, B.x, uMode);
  float flooded = step(tB, uLevel + 0.0005);
  float depth = flooded * max(surf - z, 0.04);
  float ngf = top > 0.5 ? z + h : z - 1.5;
  vNGF = ngf;
  vId = id; vGround = z; vHeight = h; vSurf = surf; vFlood = flooded; vDepth = depth; vArr = B.y;
  vec3 p = vec3(position.x, sceneY(ngf), position.z);
  vWorld = p;
  gl_Position = projectionMatrix * viewMatrix * vec4(p, 1.0);
}`;

export const buildingFS = /* glsl */ `
${COMMON}
uniform vec3 uWallCol; uniform vec3 uRoofCol; uniform vec3 uWindowCol; uniform float uWindowStrength;
uniform vec3 uRamp[5];
uniform vec3 uWaterTint;
uniform float uHover;
uniform float uSelected;
uniform float uDim;
varying vec3 vWorld;
flat varying float vId;
flat varying float vGround;
flat varying float vHeight;
flat varying float vSurf;
flat varying float vFlood;
flat varying float vDepth;
flat varying float vArr;
varying float vNGF;

vec3 rampColor(float d) {
  if (d < 0.8) return mix(uRamp[0], uRamp[1], d / 0.8);
  if (d < 2.0) return mix(uRamp[1], uRamp[2], (d - 0.8) / 1.2);
  if (d < 4.0) return mix(uRamp[2], uRamp[3], (d - 2.0) / 2.0);
  return mix(uRamp[3], uRamp[4], clamp((d - 4.0) / 3.0, 0.0, 1.0));
}

#ifdef PICK
void main() {
  float v = vId + 1.0;
  gl_FragColor = vec4(mod(v, 256.0) / 255.0, mod(floor(v / 256.0), 256.0) / 255.0, floor(v / 65536.0) / 255.0, 1.0);
}
#else
void main() {
  vec3 dx = dFdx(vWorld), dy = dFdy(vWorld);
  vec3 n = normalize(cross(dx, dy));
  vec3 V = normalize(cameraPosition - vWorld);
  if (dot(n, V) < 0.0) n = -n;
  bool roof = n.y > 0.7;
  float r1 = fract(sin(vId * 12.9898) * 43758.5453);
  float r2 = fract(sin(vId * 78.233 + 1.7) * 12543.1);

  float hAbove = vNGF - vGround;
  vec3 base = roof ? uRoofCol * (0.80 + 0.40 * r2) : uWallCol * (0.84 + 0.30 * r1);
  float ao = roof ? 1.0 : mix(0.50, 1.0, smoothstep(0.0, 16.0, hAbove));
  vec3 hemi = mix(uAmbGround, uAmbSky, n.y * 0.5 + 0.5);
  float ndl = max(dot(n, normalize(uSunDir)), 0.0);
  vec3 c = base * (hemi * uAmbient + uSunCol * ndl) * ao;

  // lit windows on the walls (night): a 3.1 m x 2.7 m grid, faded out when it would alias
  if (!roof && uWindowStrength > 0.0) {
    vec2 tang = normalize(vec2(-n.z, n.x));
    vec2 cellUV = vec2(dot(vWorld.xz, tang) / 2.7, hAbove / 3.1);
    vec2 f = fract(cellUV), id2 = floor(cellUV);
    float win = step(0.22, f.x) * step(f.x, 0.78) * step(0.28, f.y) * step(f.y, 0.78);
    float lit = step(0.62, hash12(id2 + vId * 0.37));
    float aa = 1.0 - smoothstep(0.35, 1.0, fwidth(cellUV.x) + fwidth(cellUV.y));
    float floor0 = step(2.5, hAbove);
    c += uWindowCol * win * lit * aa * floor0 * uWindowStrength * (0.55 + 0.6 * hash12(id2 + 9.1));
  }

  // flooding
  float fl = vFlood;
  if (fl > 0.5) {
    vec3 sev = rampColor(vDepth);
    float under = 1.0 - smoothstep(vSurf - 0.05, vSurf + 0.05, vNGF);
    // everything above the waterline glows in the severity colour, roofs the most
    float tint = roof ? 0.80 : 0.34;
    c = mix(c, sev * (roof ? 0.95 : 0.80), tint * (1.0 - under));
    c += sev * 0.16 * (1.0 - under);
    // submerged part of the wall: seen through the water
    c = mix(c, uWaterTint * (0.55 + 0.45 * ao), under * 0.82);
    float wl = exp(-pow((vNGF - vSurf) / 0.22, 2.0));
    c += vec3(0.55, 0.95, 1.0) * wl * 0.9 * (roof ? 0.0 : 1.0);
  }
  c *= mix(1.0, 0.45, uDim * (1.0 - fl));

  if (abs(vId - uHover) < 0.5 || abs(vId - uSelected) < 0.5) {
    float fres = pow(1.0 - max(dot(n, V), 0.0), 2.0);
    c = mix(c, vec3(1.0, 0.98, 0.9), 0.35) + vec3(1.0, 0.9, 0.7) * fres * 0.4;
  }
  c = applyFog(c, distance(cameraPosition, vWorld));
  gl_FragColor = vec4(toDisplay(c), 1.0);
}
#endif`;

// ----------------------------------------------------------------------------------- lines on the ground
export const lineVS = /* glsl */ `
${COMMON}
varying vec3 vWorld;
void main() {
  vec2 xz = position.xz;
  float ngf = groundAt(xzToUV(xz));
  vec3 p = vec3(xz.x, sceneY(ngf) + 0.6, xz.y);
  vWorld = p;
  gl_Position = projectionMatrix * viewMatrix * vec4(p, 1.0);
}`;
export const lineFS = /* glsl */ `
${COMMON}
uniform vec3 uLineCol; uniform float uLineAlpha;
varying vec3 vWorld;
void main() {
  float d = distance(cameraPosition, vWorld);
  vec3 c = applyFog(uLineCol, d);
  gl_FragColor = vec4(toDisplay(c), uLineAlpha);
}`;

// ----------------------------------------------------------------------------------- PPRI overlay (draped on the terrain mesh)
export const ppriVS = /* glsl */ `
${COMMON}
varying vec2 vUV;
varying vec3 vWorld;
void main() {
  vec2 xz = position.xz;
  vUV = xzToUV(xz);
  float ngf = groundAt(vUV);
  vec3 p = vec3(xz.x, sceneY(ngf) + 0.35, xz.y);
  vWorld = p;
  gl_Position = projectionMatrix * viewMatrix * vec4(p, 1.0);
}`;
export const ppriFS = /* glsl */ `
${COMMON}
uniform sampler2D tPpriA; // BC, BS, R, V coverage
uniform sampler2D tPpriB; // BCH, BSH coverage (hatched)
uniform vec3 uBC; uniform vec3 uBS; uniform vec3 uR; uniform vec3 uV;
uniform float uOpacity;
varying vec2 vUV;
varying vec3 vWorld;
void main() {
  vec4 a = texture2D(tPpriA, vUV);
  vec2 b = texture2D(tPpriB, vUV).rg;
  float cov = max(max(max(a.r, a.g), max(a.b, a.a)), max(b.r, b.g));
  if (cov < 0.02) discard;
  // diagonal hatching for the "H" (extension) sectors
  float hatch = step(0.5, fract((vWorld.x + vWorld.z) / 9.0));
  float wA = a.r + a.g + a.b + a.a + 1e-4;
  float wB = b.r + b.g + 1e-4;
  vec3 colA = (uBC * a.r + uBS * a.g + uR * a.b + uV * a.a) / wA;
  vec3 colB = (uBC * b.r + uBS * b.g) / wB;
  float covA = clamp(max(max(a.r, a.g), max(a.b, a.a)), 0.0, 1.0);
  float covB = clamp(max(b.r, b.g), 0.0, 1.0);
  float fillA = smoothstep(0.35, 0.65, covA) * 0.34;
  float fillB = smoothstep(0.35, 0.65, covB) * (0.12 + 0.30 * hatch);
  // outline = where coverage crosses 0.5
  float cMax = max(covA, covB);
  float w = fwidth(cMax) + 1e-3;
  float edge = 1.0 - clamp(abs(cMax - 0.5) / (w * 1.4), 0.0, 1.0);
  vec3 col = covA >= covB ? colA : colB;
  float alpha = max(fillA, fillB);
  alpha = max(alpha, edge * 0.95);
  vec3 c = applyFog(col, distance(cameraPosition, vWorld));
  gl_FragColor = vec4(toDisplay(c * 1.25), alpha * uOpacity);
}`;

// ----------------------------------------------------------------------------------- stations (instanced billboards)
export const stationVS = /* glsl */ `
${COMMON}
attribute vec3 iPos;    // x, ground NGF, z
attribute vec4 iThr;    // connected threshold (m), level-only threshold (m), mode id, index
uniform vec2 uViewport;
uniform float uHoverSt;
uniform float uSelectedSt;
uniform float uPoleH;
varying vec2 vQuad;
varying float vState;
varying float vMode;
varying float vHover;
varying float vDist;
void main() {
  float thr = mix(iThr.x, iThr.y, uMode);
  float margin = thr - uLevel;
  vState = margin <= 0.0005 ? 2.0 : (margin <= 0.5 ? 1.0 : 0.0);
  vMode = iThr.z;
  vHover = (abs(iThr.w - uHoverSt) < 0.5 || abs(iThr.w - uSelectedSt) < 0.5) ? 1.0 : 0.0;
  vec3 base = vec3(iPos.x, sceneY(iPos.y), iPos.z);
  float poleH = uPoleH * (0.35 + 0.65 * min(1.0, distance(cameraPosition, base) / 2500.0));
  vec3 top = base + vec3(0.0, poleH, 0.0);
  vec4 clip = projectionMatrix * viewMatrix * vec4(top, 1.0);
  vDist = distance(cameraPosition, base);
  float px = clamp(16.0 + 1.0 * vState * 4.0 + vHover * 8.0, 10.0, 40.0);
  vec2 q = position.xy;            // -1..1 quad
  vQuad = q;
  vec2 ndcOff = q * px / uViewport * 2.0;
  clip.xy += ndcOff * clip.w * 0.5;
  gl_Position = clip;
}`;
export const stationFS = /* glsl */ `
uniform float uTime;
uniform float uStationDim;
varying vec2 vQuad;
varying float vState;
varying float vMode;
varying float vHover;
varying float vDist;
float sdRoundBox(vec2 p, vec2 b, float r) { vec2 q = abs(p) - b + r; return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r; }
void main() {
  vec2 p = vQuad;
  float r = length(p);
  float aa = fwidth(r) * 1.2;
  // state colours: safe = cool white, alert = amber, flooded = red
  vec3 col = vState > 1.5 ? vec3(1.0, 0.22, 0.30) : (vState > 0.5 ? vec3(1.0, 0.70, 0.12) : vec3(0.86, 0.93, 1.0));
  float disc = 1.0 - smoothstep(0.78 - aa, 0.78, r);
  float ring = smoothstep(0.78 - aa * 2.0, 0.78 - aa, r) * (1.0 - smoothstep(0.78 - aa, 0.78, r));
  float inner = 1.0 - smoothstep(0.56 - aa, 0.56, r);
  // glyph: metro = M-like bars, rail = double bar, RER = R-chevron; kept simple and readable
  vec3 dark = vec3(0.04, 0.07, 0.12);
  vec3 c = col * disc;
  c = mix(c, dark, inner * 0.92);
  float glyph = 0.0;
  if (vMode < 0.5) { // metro: M
    float bars = step(abs(p.x + 0.26), 0.07) + step(abs(p.x - 0.26), 0.07);
    float slope = step(abs(abs(p.x) - (0.26 - (p.y * -0.5 + 0.0) * 0.5)), 0.001);
    float v = step(abs(p.y), 0.30);
    float diag = step(abs(p.y - (0.30 - abs(p.x) * 1.15)), 0.075) * step(abs(p.x), 0.27) * step(p.y, 0.32) * step(-0.30, p.y);
    glyph = clamp(bars * v + diag, 0.0, 1.0);
  } else if (vMode < 1.5) { // RER: R-ish ring bars
    glyph = step(abs(p.x + 0.15), 0.07) * step(abs(p.y), 0.30) + step(abs(p.y - 0.18), 0.06) * step(abs(p.x - 0.08), 0.22) + step(abs(p.y + 0.02), 0.06) * step(abs(p.x - 0.06), 0.18)
          + step(abs(p.x - 0.27), 0.06) * step(abs(p.y - 0.10), 0.12);
    glyph = clamp(glyph, 0.0, 1.0);
  } else if (vMode < 2.5) { // rail: two rails + sleepers
    glyph = (step(abs(abs(p.x) - 0.17), 0.05) * step(abs(p.y), 0.32)) + step(abs(fract(p.y * 2.2 + 0.5) - 0.5), 0.1) * step(abs(p.x), 0.22) * step(abs(p.y), 0.3);
    glyph = clamp(glyph, 0.0, 1.0);
  } else { // tram: T
    glyph = step(abs(p.y - 0.2), 0.08) * step(abs(p.x), 0.3) + step(abs(p.x), 0.08) * step(abs(p.y + 0.05), 0.3);
    glyph = clamp(glyph, 0.0, 1.0);
  }
  c = mix(c, col, glyph * inner);
  float pulse = vState > 1.5 ? 0.5 + 0.5 * sin(uTime * 4.0) : 0.0;
  float halo = (1.0 - smoothstep(0.78, 1.0, r)) * (vState > 0.5 ? 0.45 + 0.4 * pulse : 0.0) * (1.0 - disc);
  float a = max(disc, halo) * (1.0 - uStationDim);
  vec3 outc = c + col * halo;
  outc = mix(outc, vec3(1.0), vHover * 0.25);
  if (a < 0.02) discard;
  gl_FragColor = vec4(pow(outc, vec3(1.0 / 1.0)), a);
}`;
export const poleVS = /* glsl */ `
${COMMON}
attribute vec3 iPos;
attribute vec4 iThr;
uniform float uPoleH;
varying float vState;
void main() {
  float thr = mix(iThr.x, iThr.y, uMode);
  float margin = thr - uLevel;
  vState = margin <= 0.0005 ? 2.0 : (margin <= 0.5 ? 1.0 : 0.0);
  vec3 base = vec3(iPos.x, sceneY(iPos.y), iPos.z);
  float poleH = uPoleH * (0.35 + 0.65 * min(1.0, distance(cameraPosition, base) / 2500.0));
  vec3 p = base + vec3(0.0, position.y * poleH, 0.0);
  gl_Position = projectionMatrix * viewMatrix * vec4(p, 1.0);
}`;
export const poleFS = /* glsl */ `
varying float vState;
uniform float uStationDim;
void main() {
  vec3 col = vState > 1.5 ? vec3(1.0, 0.22, 0.30) : (vState > 0.5 ? vec3(1.0, 0.70, 0.12) : vec3(0.7, 0.8, 0.95));
  gl_FragColor = vec4(col, 0.8 * (1.0 - uStationDim));
}`;

