// All GLSL lives here. Everything flood-related is evaluated on the GPU from the slider value
// (uLevel, metres on the Pont d'Austerlitz gauge), so the 3D water, the flooded streets and the
// building colours update in the same frame with no CPU work.

export const COMMON = /* glsl */ `
uniform float uLevel;      // gauge reading (m)
uniform float uExag;       // vertical exaggeration
uniform float uMode;       // 0 = connected flooding, 1 = any low point (sewers / underground network)
uniform float uTime;
uniform vec4  uHydro;      // gauge zero NGF, slope m/km, slope ramp start, slope ramp end
uniform vec2  uWorld;      // size of the grid in metres
uniform vec2  uGridSize;   // grid cells
uniform vec2  uSSize;      // river-abscissa texture size
uniform sampler2D tGround; // R32F NGF altitude of the ground
uniform sampler2D tFlood;  // R32F connected flood threshold (gauge m)
uniform sampler2D tRiverS; // R32F river abscissa (km downstream of Austerlitz), low-res
uniform sampler2D tMasks;  // RGBA8: buildings, parks, canals, domain coverage
uniform vec3  uFogCol;
uniform float uFogDensity;
uniform vec3  uSunDir;
uniform vec3  uSunCol;
uniform vec3  uAmbSky;
uniform vec3  uAmbGround;
uniform float uAmbient;
uniform float uExposure;

const float Y_REF = 25.0;

float slopeK(float L) {
  float t = clamp((L - uHydro.z) / (uHydro.w - uHydro.z), 0.0, 1.0);
  return uHydro.y * t * t * (3.0 - 2.0 * t);
}
float surfaceZ(float L, float s) { return uHydro.x + L - slopeK(L) * s; }
float sceneY(float ngf) { return (ngf - Y_REF) * uExag; }
vec2 xzToUV(vec2 xz) { return (xz + uWorld * 0.5) / uWorld; }

float bil(sampler2D t, vec2 uv, vec2 size) {
  vec2 p = uv * size - 0.5;
  vec2 f = fract(p);
  ivec2 i = ivec2(floor(p));
  ivec2 m = ivec2(size) - 1;
  float a = texelFetch(t, clamp(i, ivec2(0), m), 0).r;
  float b = texelFetch(t, clamp(i + ivec2(1, 0), ivec2(0), m), 0).r;
  float c = texelFetch(t, clamp(i + ivec2(0, 1), ivec2(0), m), 0).r;
  float d = texelFetch(t, clamp(i + ivec2(1, 1), ivec2(0), m), 0).r;
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float groundAt(vec2 uv) { return bil(tGround, uv, uGridSize); }
float floodTAt(vec2 uv) { return bil(tFlood, uv, uGridSize); }
float riverSAt(vec2 uv) { return bil(tRiverS, uv, uSSize); }

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1, 0)), u.x), mix(hash12(i + vec2(0, 1)), hash12(i + vec2(1, 1)), u.x), u.y);
}

vec3 applyFog(vec3 c, float dist) {
  float f = 1.0 - exp(-pow(dist * uFogDensity, 2.0));
  return mix(c, uFogCol, clamp(f, 0.0, 1.0));
}
// filmic tone map + display gamma
vec3 toDisplay(vec3 c) {
  c *= uExposure;
  c = (c * (2.51 * c + 0.03)) / (c * (2.43 * c + 0.59) + 0.14);
  return pow(clamp(c, 0.0, 1.0), vec3(1.0 / 2.2));
}
`;

// ----------------------------------------------------------------------------------- sky
export const skyVS = /* glsl */ `
uniform mat4 uInvProj;
uniform mat4 uCamWorld;
varying vec3 vRay;
void main() {
  vec4 v = uInvProj * vec4(position.xy, 1.0, 1.0);
  vRay = (uCamWorld * vec4(v.xyz, 0.0)).xyz;
  gl_Position = vec4(position.xy, 0.99999, 1.0);
}`;
export const skyFS = /* glsl */ `
uniform vec3 uSkyTop; uniform vec3 uSkyMid; uniform vec3 uSkyHorizon; uniform vec3 uSunDir; uniform vec3 uSunCol;
uniform float uNight; uniform float uExposure;
varying vec3 vRay;
float h21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
void main() {
  vec3 d = normalize(vRay);
  float e = d.y;
  vec3 c = mix(uSkyHorizon, uSkyMid, smoothstep(0.0, 0.22, e));
  c = mix(c, uSkyTop, smoothstep(0.15, 0.85, e));
  // below the horizon: fade towards the horizon colour (the city floats in the haze)
  c = mix(c, uSkyHorizon * 0.55, smoothstep(0.0, -0.35, e));
  float sd = max(dot(d, normalize(uSunDir)), 0.0);
  c += uSunCol * (pow(sd, 400.0) * 1.2 + pow(sd, 12.0) * 0.10);
  if (uNight > 0.5 && e > 0.0) {
    vec2 g = floor(d.xz / (d.y + 0.35) * 160.0);
    float s = step(0.9965, h21(g));
    c += vec3(0.8, 0.9, 1.0) * s * smoothstep(0.05, 0.4, e) * 0.9;
  }
  c = c * uExposure;
  gl_FragColor = vec4(pow(clamp(c, 0.0, 1.0), vec3(1.0 / 2.2)), 1.0);
}`;

