// ----------------------------------------------------------------------------------- PPRI overlay (draped on the terrain mesh)
export const ppriVS = /* glsl */ `
${COMMON}
varying vec2 vUV;
varying vec3 vWorld;
void main() {
  vec2 xz = position.xz;
  vUV = xzToUV(xz);
  float ngf = groundAt(vUV);
  vec3 p = vec3(xz.x, sceneY(ngf) + 0.35, xz.y);
