// Turns footprint rings into extruded geometry (walls + earcut roofs) for one spatial chunk.
// Vertex layout: position = (x, id*2 + isTop, z); the vertex shader fetches ground/height per building id.
import earcut from 'earcut';

self.onmessage = (e) => {
  const { chunk, b0, nB, ringCount, ringLen, origin, xy, Q } = e.data;
  let nv = 0;
  for (let i = 0; i < ringLen.length; i++) nv += ringLen[i];
  const pos = new Float32Array(nv * 2 * 3);
  const idx = new Uint32Array(nv * 9 + 64);
  let ni = 0, vbase = 0, ri = 0, xyo = 0;
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;

  for (let b = 0; b < nB; b++) {
    const gid = b0 + b;
    const ox = origin[2 * b], oy = origin[2 * b + 1];
    const rc = ringCount[b];
    const startVBase = vbase;
    const flat = [];
    const holes = [];
    let local = 0;
    for (let r = 0; r < rc; r++) {
      const len = ringLen[ri++];
      if (r > 0) holes.push(local);
      for (let k = 0; k < len; k++) {
        const x = (ox + xy[xyo]) / Q;
        const z = -(oy + xy[xyo + 1]) / Q;
        xyo += 2;
        const v = (startVBase + local + k) * 2;
        pos[v * 3] = x; pos[v * 3 + 1] = gid * 2; pos[v * 3 + 2] = z;
        pos[v * 3 + 3] = x; pos[v * 3 + 4] = gid * 2 + 1; pos[v * 3 + 5] = z;
        flat.push(x, z);
        if (x < minX) minX = x; if (x > maxX) maxX = x;
        if (z < minZ) minZ = z; if (z > maxZ) maxZ = z;
      }
      // walls
      for (let k = 0; k < len; k++) {
        const a = startVBase + local + k;
        const n = startVBase + local + ((k + 1) % len);
        const b0i = a * 2, t0 = a * 2 + 1, b1i = n * 2, t1 = n * 2 + 1;
        idx[ni++] = b0i; idx[ni++] = b1i; idx[ni++] = t1;
        idx[ni++] = b0i; idx[ni++] = t1; idx[ni++] = t0;
      }
      local += len;
    }
    // roof
    const tris = earcut(flat, holes.length ? holes : undefined, 2);
    for (let t = 0; t < tris.length; t++) idx[ni++] = (startVBase + tris[t]) * 2 + 1;
    vbase += local;
  }
  const index = idx.slice(0, ni);
  self.postMessage({ chunk, pos, index, bounds: [minX, maxX, minZ, maxZ], b0, nB }, [pos.buffer, index.buffer]);
};

