import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { THEMES, col, DEPTH_RAMP, Y_REF } from './config.js';
import * as S from './gl/shaders.js';

const V3 = (a) => new THREE.Vector3(a[0], a[1], a[2]);
const modeId = (modes) => (modes.includes('METRO') ? 0 : modes.includes('RER') ? 1 : modes.includes('TRAIN') ? 2 : 3);

export class City {
  constructor(canvas, data, opts = {}) {
    this.canvas = canvas;
    this.data = data;
    const g = data.meta.grid;
    this.Wm = g.w * g.cell; this.Hm = g.h * g.cell;
    this.themeName = opts.theme || 'night';
    this.opts = opts;

    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
    this.maxPR = Math.min(window.devicePixelRatio || 1, opts.maxDpr || 2);
    this.pr = opts.fixedDpr || this.maxPR;
    this.renderer.setPixelRatio(this.pr);
    this.renderer.setClearColor(0x000000, 1);
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(40, 1, 5, 90000);
    this.clock = new THREE.Clock();
    this.listeners = {};

    this.buildUniforms();
    this.buildTextures();
    this.buildSky();
    this.buildTerrain();
    this.buildWater();
    this.buildLines();
    this.buildStations();
    this.buildingMeshes = [];
    this.setTheme(this.themeName);
    this.setupControls();
    this.pickTarget = new THREE.WebGLRenderTarget(1, 1, { type: THREE.UnsignedByteType, format: THREE.RGBAFormat, depthBuffer: true });
    this.pickBuf = new Uint8Array(4);
    window.addEventListener('resize', () => this.resize());
    this.resize();
    this.frameTimes = [];
  }

  on(ev, fn) { (this.listeners[ev] ||= []).push(fn); }
  emit(ev, ...a) { (this.listeners[ev] || []).forEach((f) => f(...a)); }

  // ------------------------------------------------------------------------- uniforms & textures
  buildUniforms() {
    const m = this.data.meta, g = m.grid, h = m.hydro;
    this.shared = {
      uLevel: { value: 0 }, uExag: { value: 1 }, uMode: { value: 0 }, uTime: { value: 0 },
      uHydro: { value: new THREE.Vector4(h.gaugeZeroNgf, h.slopeKm, h.slopeL0, h.slopeL1) },
      uWorld: { value: new THREE.Vector2(this.Wm, this.Hm) },
      uGridSize: { value: new THREE.Vector2(g.w, g.h) },
      uSSize: { value: new THREE.Vector2(g.sW, g.sH) },
      tGround: { value: null }, tFlood: { value: null }, tRiverS: { value: null }, tMasks: { value: null },
      uFogCol: { value: new THREE.Vector3() }, uFogDensity: { value: 0.00005 },
      uSunDir: { value: new THREE.Vector3(-0.4, 0.6, -0.5).normalize() }, uSunCol: { value: new THREE.Vector3() },
      uAmbSky: { value: new THREE.Vector3() }, uAmbGround: { value: new THREE.Vector3() }, uAmbient: { value: 1 },
      uExposure: { value: 1.15 },
    };
  }

  buildTextures() {
    const { ground, T, riverS, masks, grid: g } = this.data;
    const n = g.w * g.h;
    const gf = new Float32Array(n);
    for (let i = 0; i < n; i++) gf[i] = ground[i] / 100 + g.groundBase;
    const tf = new Float32Array(n);
    for (let i = 0; i < n; i++) tf[i] = Math.min(T[i], 2500) / 100;
    const mk = (arr, w, h, fmt, type, filter) => {
      const t = new THREE.DataTexture(arr, w, h, fmt, type);
      t.minFilter = t.magFilter = filter; t.generateMipmaps = false; t.flipY = false;
      t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping; t.needsUpdate = true;
      return t;
    };
    this.tex = {
      ground: mk(gf, g.w, g.h, THREE.RedFormat, THREE.FloatType, THREE.NearestFilter),
      flood: mk(tf, g.w, g.h, THREE.RedFormat, THREE.FloatType, THREE.NearestFilter),
      riverS: mk(riverS, g.sW, g.sH, THREE.RedFormat, THREE.FloatType, THREE.NearestFilter),
      masks: mk(masks, g.w, g.h, THREE.RGBAFormat, THREE.UnsignedByteType, THREE.LinearFilter),
    };
    this.shared.tGround.value = this.tex.ground; this.shared.tFlood.value = this.tex.flood;
    this.shared.tRiverS.value = this.tex.riverS; this.shared.tMasks.value = this.tex.masks;

    // building attribute textures (2 RGBA32F texels per building, same index)
    const { attr } = this.data.buildings;
    const nb = attr.z.length, W = 512, H = Math.ceil(nb / W);
    const A = new Float32Array(W * H * 4), B = new Float32Array(W * H * 4);
    for (let i = 0; i < nb; i++) {
      A[i * 4] = attr.z[i]; A[i * 4 + 1] = attr.h[i]; A[i * 4 + 2] = Math.min(attr.tc[i], 2500) / 100; A[i * 4 + 3] = attr.s[i];
      B[i * 4] = Math.min(attr.tl[i], 2500) / 100; B[i * 4 + 1] = attr.arr[i]; B[i * 4 + 2] = attr.flags[i]; B[i * 4 + 3] = attr.year[i];
    }
    this.bldTex = { A: mk(A, W, H, THREE.RGBAFormat, THREE.FloatType, THREE.NearestFilter), B: mk(B, W, H, THREE.RGBAFormat, THREE.FloatType, THREE.NearestFilter), size: new THREE.Vector2(W, H) };
  }

  // ------------------------------------------------------------------------- scene objects
  gridGeometry(step) {
    const nx = Math.floor(this.Wm / step) + 1, nz = Math.floor(this.Hm / step) + 1;
    const pos = new Float32Array(nx * nz * 3);
    for (let j = 0, k = 0; j < nz; j++) for (let i = 0; i < nx; i++, k += 3) {
      pos[k] = -this.Wm / 2 + i * step; pos[k + 2] = -this.Hm / 2 + j * step;
    }
    const idx = new Uint32Array((nx - 1) * (nz - 1) * 6);
    let o = 0;
    for (let j = 0; j < nz - 1; j++) for (let i = 0; i < nx - 1; i++) {
      const a = j * nx + i, b = a + 1, c = a + nx, d = c + 1;
      idx[o++] = a; idx[o++] = c; idx[o++] = b; idx[o++] = b; idx[o++] = c; idx[o++] = d;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setIndex(new THREE.BufferAttribute(idx, 1));
    return geo;
  }

  mat(vs, fs, uniforms = {}, opts = {}) {
    return new THREE.ShaderMaterial({ vertexShader: vs, fragmentShader: fs, uniforms: Object.assign({}, this.shared, uniforms), ...opts });
  }

  buildSky() {
    const geo = new THREE.PlaneGeometry(2, 2);
    this.skyU = {
      uInvProj: { value: new THREE.Matrix4() }, uCamWorld: { value: new THREE.Matrix4() },
      uSkyTop: { value: new THREE.Vector3() }, uSkyMid: { value: new THREE.Vector3() }, uSkyHorizon: { value: new THREE.Vector3() }, uNight: { value: 1 },
    };
    this.sky = new THREE.Mesh(geo, this.mat(S.skyVS, S.skyFS, this.skyU, { depthWrite: false, depthTest: false }));
    this.sky.frustumCulled = false; this.sky.renderOrder = -10;
    this.scene.add(this.sky);
  }

  buildTerrain() {
    this.terrainGeo = this.gridGeometry(15);
    this.terrainU = {
      uStreetCol: { value: new THREE.Vector3() }, uParkCol: { value: new THREE.Vector3() }, uCanalCol: { value: new THREE.Vector3() },
      uContourCol: { value: new THREE.Vector3() }, uContour: { value: 1 },
    };
    this.terrainMat = this.mat(S.terrainVS, S.terrainFS, this.terrainU);
    this.terrainPickMat = this.mat(S.terrainVS, S.terrainFS, this.terrainU, { defines: { PICK: 1 } });
    this.terrain = new THREE.Mesh(this.terrainGeo, this.terrainMat);
    this.terrain.frustumCulled = false; this.terrain.renderOrder = 0;
    this.scene.add(this.terrain);
  }

  buildWater() {
    this.waterU = {
      uShallow: { value: new THREE.Vector3() }, uDeep: { value: new THREE.Vector3() }, uRiver: { value: new THREE.Vector3() },
      uRiverDeep: { value: new THREE.Vector3() }, uSkyRefl: { value: new THREE.Vector3() }, uHorizon: { value: new THREE.Vector3() }, uGlow: { value: 1 },
    };
    this.waterGeo = this.gridGeometry(20);
    this.water = new THREE.Mesh(this.waterGeo, this.mat(S.waterVS, S.waterFS, this.waterU, { transparent: true, depthWrite: false }));
    this.water.frustumCulled = false; this.water.renderOrder = 3;
    this.scene.add(this.water);
  }

  async enablePPRI(ppri) {
    if (this.ppri) return;
    const g = this.data.meta.grid;
    const mk = (arr, fmt) => { const t = new THREE.DataTexture(arr, g.w, g.h, fmt, THREE.UnsignedByteType); t.minFilter = t.magFilter = THREE.LinearFilter; t.generateMipmaps = false; t.needsUpdate = true; return t; };
    this.ppriU = {
      tPpriA: { value: mk(ppri.a, THREE.RGBAFormat) }, tPpriB: { value: mk(ppri.b, THREE.RGFormat) },
      uBC: { value: new THREE.Vector3() }, uBS: { value: new THREE.Vector3() }, uR: { value: new THREE.Vector3() }, uV: { value: new THREE.Vector3() },
      uOpacity: { value: 1 },
    };
    this.ppri = new THREE.Mesh(this.terrainGeo, this.mat(S.ppriVS, S.ppriFS, this.ppriU, { transparent: true, depthWrite: false }));
    this.ppri.frustumCulled = false; this.ppri.renderOrder = 4; this.ppri.visible = false;
    this.scene.add(this.ppri);
    this.applyThemeToPPRI();
  }

  buildLines() {
    const sub = (pts, maxLen = 30) => {
      const out = [];
      for (let i = 0; i < pts.length - 1; i++) {
        const [x0, z0] = pts[i], [x1, z1] = pts[i + 1];
        const n = Math.max(1, Math.ceil(Math.hypot(x1 - x0, z1 - z0) / maxLen));
        for (let k = 0; k < n; k++) {
          const a = k / n, b = (k + 1) / n;
          out.push(x0 + (x1 - x0) * a, 0, z0 + (z1 - z0) * a, x0 + (x1 - x0) * b, 0, z0 + (z1 - z0) * b);
        }
      }
      return out;
    };
    const mkLines = (polylines, uniforms, order) => {
      const arr = [];
      for (const pl of polylines) arr.push(...sub(pl));
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(arr), 3));
      const m = new THREE.LineSegments(geo, this.mat(S.lineVS, S.lineFS, uniforms, { transparent: true, depthWrite: false }));
      m.frustumCulled = false; m.renderOrder = order;
      this.scene.add(m);
      return m;
    };
    const arrLines = [];
    for (const a of this.data.meta.arrondissements) arrLines.push(...a.outline);
    this.arrU = { uLineCol: { value: new THREE.Vector3() }, uLineAlpha: { value: 0.55 } };
    this.arrLines = mkLines(arrLines, this.arrU, 5);
    this.domU = { uLineCol: { value: new THREE.Vector3() }, uLineAlpha: { value: 0.95 } };
    this.domLine = mkLines(this.data.meta.domain, this.domU, 5);
  }

  buildStations() {
    const st = this.data.stations;
    const n = st.length;
    const iPos = new Float32Array(n * 3), iThr = new Float32Array(n * 4);
    st.forEach((s, i) => {
      iPos[i * 3] = s.x; iPos[i * 3 + 1] = s.ngf; iPos[i * 3 + 2] = s.z;
      iThr[i * 4] = Math.min(s.tc, 2500) / 100; iThr[i * 4 + 1] = Math.min(s.tl, 2500) / 100; iThr[i * 4 + 2] = modeId(s.modes); iThr[i * 4 + 3] = i;
      s.mode = modeId(s.modes);
    });
    this.stU = { uViewport: { value: new THREE.Vector2(1, 1) }, uHoverSt: { value: -1 }, uSelectedSt: { value: -1 }, uPoleH: { value: 60 }, uStationDim: { value: 0 } };
    // sprites
    const quad = new THREE.InstancedBufferGeometry();
    quad.setAttribute('position', new THREE.BufferAttribute(new Float32Array([-1, -1, 0, 1, -1, 0, 1, 1, 0, -1, 1, 0]), 3));
    quad.setIndex([0, 1, 2, 0, 2, 3]);
    quad.setAttribute('iPos', new THREE.InstancedBufferAttribute(iPos, 3));
    quad.setAttribute('iThr', new THREE.InstancedBufferAttribute(iThr, 4));
    quad.instanceCount = n;
    this.stationSprites = new THREE.Mesh(quad, this.mat(S.stationVS, S.stationFS, this.stU, { transparent: true, depthWrite: false, depthTest: false }));
    this.stationSprites.frustumCulled = false; this.stationSprites.renderOrder = 8;
    // poles
    const pole = new THREE.InstancedBufferGeometry();
    pole.setAttribute('position', new THREE.BufferAttribute(new Float32Array([0, 0, 0, 0, 1, 0]), 3));
    pole.setAttribute('iPos', new THREE.InstancedBufferAttribute(iPos, 3));
    pole.setAttribute('iThr', new THREE.InstancedBufferAttribute(iThr, 4));
    pole.instanceCount = n;
    this.stationPoles = new THREE.LineSegments(pole, this.mat(S.poleVS, S.poleFS, this.stU, { transparent: true, depthWrite: false }));
    this.stationPoles.frustumCulled = false; this.stationPoles.renderOrder = 7;
    this.stationGroup = new THREE.Group();
    this.stationGroup.add(this.stationPoles, this.stationSprites);
    this.scene.add(this.stationGroup);
    this.stationPos = st.map((s) => new THREE.Vector3(s.x, 0, s.z));
  }

  // ------------------------------------------------------------------------- buildings
  /** Triangulates all chunks in workers; resolves when every chunk has been added. */
  async loadBuildings(onProgress) {
    const { geom } = this.data.buildings;
    const nChunks = geom.nChunks;
    // prefix sums: rings and vertices per building
    const ringStart = new Uint32Array(geom.n + 1), vertStart = new Uint32Array(geom.n + 1);
    {
      let r = 0, v = 0;
      for (let b = 0; b < geom.n; b++) {
        ringStart[b] = r; vertStart[b] = v;
        const rc = geom.ringCount[b];
        for (let k = 0; k < rc; k++) v += geom.ringLen[r + k];
        r += rc;
      }
      ringStart[geom.n] = r; vertStart[geom.n] = v;
    }
    const uniforms = {
      tBldA: { value: this.bldTex.A }, tBldB: { value: this.bldTex.B }, uBldTex: { value: this.bldTex.size },
      uWallCol: { value: new THREE.Vector3() }, uRoofCol: { value: new THREE.Vector3() }, uWindowCol: { value: new THREE.Vector3() }, uWindowStrength: { value: 0 },
      uRamp: { value: DEPTH_RAMP.map((h) => V3(col(h))) }, uWaterTint: { value: new THREE.Vector3() },
      uHover: { value: -1 }, uSelected: { value: -1 }, uDim: { value: 0 },
    };
    this.bldU = uniforms;
    this.bldMat = this.mat(S.buildingVS, S.buildingFS, uniforms, { side: THREE.DoubleSide });
    this.bldPickMat = this.mat(S.buildingVS, S.buildingFS, uniforms, { side: THREE.DoubleSide, defines: { PICK: 1 } });
    this.applyTheme();

    const nWorkers = Math.max(2, Math.min(6, (navigator.hardwareConcurrency || 4) - 1));
    const workers = Array.from({ length: nWorkers }, () => new Worker(new URL('./workers/buildings.worker.js', import.meta.url), { type: 'module' }));
    let next = 0, done = 0;
    this.group = new THREE.Group(); this.group.renderOrder = 1; this.scene.add(this.group);
    return new Promise((resolve, reject) => {
      const post = (w) => {
        if (next >= nChunks) return;
        const c = next++;
        const b0 = geom.chunkBounds[c], b1 = geom.chunkBounds[c + 1];
        const r0 = ringStart[b0], r1 = ringStart[b1], v0 = vertStart[b0], v1 = vertStart[b1];
        w.postMessage({
          chunk: c, b0, nB: b1 - b0,
          ringCount: geom.ringCount.slice(b0, b1), ringLen: geom.ringLen.slice(r0, r1),
          origin: geom.origin.slice(b0 * 2, b1 * 2), xy: geom.xy.slice(v0 * 2, v1 * 2), Q: 10,
        });
      };
      workers.forEach((w) => {
        w.onerror = (e) => reject(e);
        w.onmessage = (e) => {
          this.addChunk(e.data);
          done++;
          onProgress?.(done / nChunks);
          if (done === nChunks) { workers.forEach((x) => x.terminate()); resolve(); } else post(w);
        };
        post(w);
      });
    });
  }

  addChunk({ pos, index, bounds }) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setIndex(new THREE.BufferAttribute(index, 1));
    const cx = (bounds[0] + bounds[1]) / 2, cz = (bounds[2] + bounds[3]) / 2;
    const r = Math.hypot(bounds[1] - bounds[0], bounds[3] - bounds[2]) / 2;
    geo.boundingSphere = new THREE.Sphere(new THREE.Vector3(cx, 60, cz), r + 400);
    const mesh = new THREE.Mesh(geo, this.bldMat);
    mesh.renderOrder = 1;
    this.group.add(mesh);
    this.buildingMeshes.push(mesh);
  }

  // ------------------------------------------------------------------------- theme / state
  setTheme(name) {
    this.themeName = name; this.theme = THEMES[name];
    document.documentElement.dataset.theme = this.theme.css;
    this.applyTheme();
  }

  applyTheme() {
    const t = this.theme, s = this.shared;
    s.uFogCol.value.set(...col(t.fog)); s.uFogDensity.value = t.fogDensity;
    s.uSunCol.value.set(...col(t.sun).map((v) => v * t.sunStrength));
    s.uSunDir.value.set(...t.sunDir).normalize();
    s.uAmbSky.value.set(...col(t.ambSky)); s.uAmbGround.value.set(...col(t.ambGround)); s.uAmbient.value = t.ambient;
    s.uExposure.value = name_exposure[this.themeName];
    this.skyU.uSkyTop.value.set(...col(t.skyTop)); this.skyU.uSkyMid.value.set(...col(t.skyMid)); this.skyU.uSkyHorizon.value.set(...col(t.skyHorizon));
    this.skyU.uNight.value = this.themeName === 'night' ? 1 : 0;
    const tu = this.terrainU;
    tu.uStreetCol.value.set(...col(t.street)); tu.uParkCol.value.set(...col(t.park)); tu.uCanalCol.value.set(...col(t.canal)); tu.uContourCol.value.set(...col(t.contour));
    const w = this.waterU;
    w.uShallow.value.set(...col(t.waterShallow)); w.uDeep.value.set(...col(t.waterDeep)); w.uRiver.value.set(...col(t.river)); w.uRiverDeep.value.set(...col(t.riverDeep));
    w.uSkyRefl.value.set(...col(t.sky)); w.uHorizon.value.set(...col(t.skyHorizon)); w.uGlow.value = t.glow;
    this.arrU.uLineCol.value.set(...col(this.themeName === 'night' ? '#7fa6c8' : '#51606d'));
    this.domU.uLineCol.value.set(...col(this.themeName === 'night' ? '#9fe0ff' : '#1d3b52'));
    if (this.bldU) {
      const b = this.bldU;
      b.uWallCol.value.set(...col(t.wall)); b.uRoofCol.value.set(...col(t.roof)); b.uWindowCol.value.set(...col(t.window)); b.uWindowStrength.value = t.windowStrength;
      b.uWaterTint.value.set(...col(t.waterDeep)).multiplyScalar(1.6);
    }
    this.applyThemeToPPRI();
  }

  applyThemeToPPRI() {
    if (!this.ppriU) return;
    const p = this.theme.ppri;
    this.ppriU.uBC.value.set(...col(p.bc)); this.ppriU.uBS.value.set(...col(p.bs)); this.ppriU.uR.value.set(...col(p.r)); this.ppriU.uV.value.set(...col(p.v));
  }

  setLevel(L) { this.shared.uLevel.value = L; }
  setMode(m) { this.shared.uMode.value = m; }
  setExag(x) { this.shared.uExag.value = x; this.exag = x; }
  setPPRI(on) { if (this.ppri) this.ppri.visible = on; this.dimForOverlay(on); }
  dimForOverlay(on) { if (this.bldU) this.bldU.uDim.value = on ? 0.25 : 0; }
  setStations(on) { this.stationGroup.visible = on; }
  setArrLines(on) { this.arrLines.visible = on; }
  setContours(on) { this.terrainU.uContour.value = on ? 1 : 0; }
  setBuildingsVisible(on) { if (this.group) this.group.visible = on; }

  // ------------------------------------------------------------------------- camera
  setupControls() {
    const c = this.controls = new OrbitControls(this.camera, this.canvas);
    c.enableDamping = true; c.dampingFactor = 0.09; c.zoomToCursor = true; c.screenSpacePanning = false;
    c.minDistance = 60; c.maxDistance = 24000; c.maxPolarAngle = 1.50; c.minPolarAngle = 0.05;
    c.rotateSpeed = 0.6; c.panSpeed = 0.9; c.zoomSpeed = 0.9;
    c.mouseButtons = { LEFT: THREE.MOUSE.ROTATE, MIDDLE: THREE.MOUSE.DOLLY, RIGHT: THREE.MOUSE.PAN };
    c.addEventListener('start', () => { this.flight = null; this.emit('interact'); });
    this.exag = 1;
    this.setView({ x: 400, z: -250, dist: 13000, az: 0.35, polar: 1.0 });
  }

  /** az: radians, 0 = camera south of target looking north; polar: angle from vertical. */
  setView({ x, z, dist, az, polar }) {
    const y = 0;
    this.controls.target.set(x, y, z);
    const sp = Math.sin(polar), cp = Math.cos(polar);
    this.camera.position.set(x + dist * sp * Math.sin(az), y + dist * cp, z + dist * sp * Math.cos(az));
    this.camera.lookAt(this.controls.target);
    this.controls.update();
  }

  currentView() {
    const t = this.controls.target, p = this.camera.position;
    const d = p.clone().sub(t); const dist = d.length();
    return { x: t.x, z: t.z, dist, az: Math.atan2(d.x, d.z), polar: Math.acos(Math.min(1, Math.max(-1, d.y / dist))) };
  }

  flyTo(view, ms = 2400) {
    const a = this.currentView();
    let da = view.az - a.az; da = Math.atan2(Math.sin(da), Math.cos(da));
    this.flight = { a, b: { ...view }, da, t0: performance.now(), ms };
  }

  stepFlight() {
    const f = this.flight; if (!f) return;
    let k = Math.min(1, (performance.now() - f.t0) / f.ms);
    const e = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
    // arc: pull back while travelling so the move reads as a flight
    const arc = Math.sin(Math.PI * e) * Math.min(1.0, Math.hypot(f.b.x - f.a.x, f.b.z - f.a.z) / 6000) * 0.55;
    const dist = Math.exp(Math.log(f.a.dist) * (1 - e) + Math.log(f.b.dist) * e) * (1 + arc);
    this.setView({
      x: f.a.x + (f.b.x - f.a.x) * e, z: f.a.z + (f.b.z - f.a.z) * e, dist,
      az: f.a.az + f.da * e, polar: f.a.polar + (f.b.polar - f.a.polar) * e,
    });
    if (k >= 1) this.flight = null;
  }

  // ------------------------------------------------------------------------- picking / projection
  project(x, y, z, out = new THREE.Vector3()) {
    out.set(x, y, z).project(this.camera);
    return { x: (out.x * 0.5 + 0.5) * this.w, y: (-out.y * 0.5 + 0.5) * this.h, visible: out.z < 1 && out.z > -1 };
  }

  groundY(x, z) {
    // CPU copy of the ground height (nearest cell) in scene units, used to anchor labels
    const g = this.data.meta.grid;
    const i = Math.min(g.w - 1, Math.max(0, Math.floor((x + this.Wm / 2) / g.cell)));
    const j = Math.min(g.h - 1, Math.max(0, Math.floor((z + this.Hm / 2) / g.cell)));
    return (this.data.ground[j * g.w + i] / 100 + g.groundBase - Y_REF) * (this.exag || 1);
  }

  pickBuilding(cx, cy) {
    if (!this.group || !this.group.visible) return -1;
    const rect = this.canvas.getBoundingClientRect();
    const x = (cx - rect.left), y = (cy - rect.top);
    if (x < 0 || y < 0 || x >= rect.width || y >= rect.height) return -1;
    const r = this.renderer;
    const prevVis = [this.sky.visible, this.water.visible, this.stationGroup.visible, this.arrLines.visible, this.domLine.visible, this.ppri?.visible];
    this.sky.visible = this.water.visible = this.stationGroup.visible = this.arrLines.visible = this.domLine.visible = false;
    if (this.ppri) this.ppri.visible = false;
    this.terrain.material = this.terrainPickMat;
    for (const m of this.buildingMeshes) m.material = this.bldPickMat;
    this.camera.setViewOffset(rect.width, rect.height, Math.floor(x), Math.floor(y), 1, 1);
    r.setRenderTarget(this.pickTarget);
    r.setClearColor(0x000000, 0); r.clear();
    r.render(this.scene, this.camera);
    r.readRenderTargetPixels(this.pickTarget, 0, 0, 1, 1, this.pickBuf);
    r.setRenderTarget(null); r.setClearColor(0x000000, 1);
    this.camera.clearViewOffset();
    this.terrain.material = this.terrainMat;
    for (const m of this.buildingMeshes) m.material = this.bldMat;
    [this.sky.visible, this.water.visible, this.stationGroup.visible, this.arrLines.visible, this.domLine.visible] = prevVis;
    if (this.ppri) this.ppri.visible = prevVis[5];
    const v = this.pickBuf[0] + this.pickBuf[1] * 256 + this.pickBuf[2] * 65536;
    return v - 1;
  }

  pickStation(cx, cy, radius = 16) {
    if (!this.stationGroup.visible) return -1;
    const rect = this.canvas.getBoundingClientRect();
    const px = cx - rect.left, py = cy - rect.top;
    let best = -1, bd = radius * radius;
    const v = new THREE.Vector3();
    const poleH = this.stU.uPoleH.value;
    this.data.stations.forEach((s, i) => {
      const y = (s.ngf - Y_REF) * (this.exag || 1);
      const dist = this.camera.position.distanceTo(v.set(s.x, y, s.z));
      const h = poleH * (0.35 + 0.65 * Math.min(1, dist / 2500));
      const p = this.project(s.x, y + h, s.z);
      if (!p.visible) return;
      const d = (p.x - px) ** 2 + (p.y - py) ** 2;
      if (d < bd) { bd = d; best = i; }
    });
    return best;
  }

  // ------------------------------------------------------------------------- frame
  resize() {
    const w = this.canvas.clientWidth || window.innerWidth, h = this.canvas.clientHeight || window.innerHeight;
    this.w = w; this.h = h;
    this.renderer.setPixelRatio(this.pr);
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h; this.camera.updateProjectionMatrix();
    this.stU.uViewport.value.set(w, h);
  }

  adaptResolution(dt) {
    if (this.opts.fixedDpr) return;
    this.frameTimes.push(dt);
    if (this.frameTimes.length < 40) return;
    const avg = this.frameTimes.reduce((a, b) => a + b, 0) / this.frameTimes.length;
    this.frameTimes.length = 0;
    let pr = this.pr;
    if (avg > 0.036 && pr > 0.6) pr = Math.max(0.6, pr * 0.85);
    else if (avg < 0.015 && pr < this.maxPR) pr = Math.min(this.maxPR, pr * 1.12);
    if (Math.abs(pr - this.pr) > 0.01) { this.pr = pr; this.resize(); }
  }

  render() {
    const dt = this.clock.getDelta();
    this.shared.uTime.value += dt;
    this.stepFlight();
    this.controls.update();
    // keep the target above the map and the camera clear of the ground
    const t = this.controls.target;
    const hx = this.Wm / 2 - 300, hz = this.Hm / 2 - 300;
    t.x = Math.max(-hx, Math.min(hx, t.x)); t.z = Math.max(-hz, Math.min(hz, t.z));
    const dist = this.camera.position.distanceTo(t);
    this.camera.near = Math.max(2, Math.min(300, dist * 0.015)); this.camera.far = 90000;
    this.camera.updateProjectionMatrix();
    this.skyU.uInvProj.value.copy(this.camera.projectionMatrixInverse);
    this.skyU.uCamWorld.value.copy(this.camera.matrixWorld);
    this.stU.uPoleH.value = 70;
    this.renderer.render(this.scene, this.camera);
    this.adaptResolution(dt);
    this.emit('frame', dt);
  }

  start() {
    const loop = () => { requestAnimationFrame(loop); if (!document.hidden) this.render(); };
    loop();
  }
}

const name_exposure = { night: 1.25, day: 1.05 };

import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { THEMES, col, DEPTH_RAMP, Y_REF } from './config.js';
import * as S from './gl/shaders.js';

const V3 = (a) => new THREE.Vector3(a[0], a[1], a[2]);
const modeId = (modes) => (modes.includes('METRO') ? 0 : modes.includes('RER') ? 1 : modes.includes('TRAIN') ? 2 : 3);

export class City {
  constructor(canvas, data, opts = {}) {
    this.canvas = canvas;
    this.data = data;
    const g = data.meta.grid;
    this.Wm = g.w * g.cell; this.Hm = g.h * g.cell;
    this.themeName = opts.theme || 'night';
    this.opts = opts;

    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
    this.maxPR = Math.min(window.devicePixelRatio || 1, opts.maxDpr || 2);
    this.pr = opts.fixedDpr || this.maxPR;
    this.renderer.setPixelRatio(this.pr);
    this.renderer.setClearColor(0x000000, 1);
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(40, 1, 5, 90000);
    this.clock = new THREE.Clock();
    this.listeners = {};

    this.buildUniforms();
    this.buildTextures();
    this.buildSky();
    this.buildTerrain();
    this.buildWater();
    this.buildLines();
    this.buildStations();
    this.buildingMeshes = [];
    this.setTheme(this.themeName);
    this.setupControls();
    this.pickTarget = new THREE.WebGLRenderTarget(1, 1, { type: THREE.UnsignedByteType, format: THREE.RGBAFormat, depthBuffer: true });
    this.pickBuf = new Uint8Array(4);
    window.addEventListener('resize', () => this.resize());
    this.resize();
    this.frameTimes = [];
  }

  on(ev, fn) { (this.listeners[ev] ||= []).push(fn); }
  emit(ev, ...a) { (this.listeners[ev] || []).forEach((f) => f(...a)); }

  // ------------------------------------------------------------------------- uniforms & textures
  buildUniforms() {
    const m = this.data.meta, g = m.grid, h = m.hydro;
    this.shared = {
      uLevel: { value: 0 }, uExag: { value: 1 }, uMode: { value: 0 }, uTime: { value: 0 },
      uHydro: { value: new THREE.Vector4(h.gaugeZeroNgf, h.slopeKm, h.slopeL0, h.slopeL1) },
      uWorld: { value: new THREE.Vector2(this.Wm, this.Hm) },
      uGridSize: { value: new THREE.Vector2(g.w, g.h) },
      uSSize: { value: new THREE.Vector2(g.sW, g.sH) },
      tGround: { value: null }, tFlood: { value: null }, tRiverS: { value: null }, tMasks: { value: null },
      uFogCol: { value: new THREE.Vector3() }, uFogDensity: { value: 0.00005 },
      uSunDir: { value: new THREE.Vector3(-0.4, 0.6, -0.5).normalize() }, uSunCol: { value: new THREE.Vector3() },
      uAmbSky: { value: new THREE.Vector3() }, uAmbGround: { value: new THREE.Vector3() }, uAmbient: { value: 1 },
      uExposure: { value: 1.15 },
    };
  }

  buildTextures() {
    const { ground, T, riverS, masks, grid: g } = this.data;
    const n = g.w * g.h;
    const gf = new Float32Array(n);
    for (let i = 0; i < n; i++) gf[i] = ground[i] / 100 + g.groundBase;
    const tf = new Float32Array(n);
    for (let i = 0; i < n; i++) tf[i] = Math.min(T[i], 2500) / 100;
    const mk = (arr, w, h, fmt, type, filter) => {
      const t = new THREE.DataTexture(arr, w, h, fmt, type);
      t.minFilter = t.magFilter = filter; t.generateMipmaps = false; t.flipY = false;
      t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping; t.needsUpdate = true;
      return t;
    };
    this.tex = {
      ground: mk(gf, g.w, g.h, THREE.RedFormat, THREE.FloatType, THREE.NearestFilter),
      flood: mk(tf, g.w, g.h, THREE.RedFormat, THREE.FloatType, THREE.NearestFilter),
      riverS: mk(riverS, g.sW, g.sH, THREE.RedFormat, THREE.FloatType, THREE.NearestFilter),
      masks: mk(masks, g.w, g.h, THREE.RGBAFormat, THREE.UnsignedByteType, THREE.LinearFilter),
    };
    this.shared.tGround.value = this.tex.ground; this.shared.tFlood.value = this.tex.flood;
    this.shared.tRiverS.value = this.tex.riverS; this.shared.tMasks.value = this.tex.masks;

    // building attribute textures (2 RGBA32F texels per building, same index)
    const { attr } = this.data.buildings;
    const nb = attr.z.length, W = 512, H = Math.ceil(nb / W);
    const A = new Float32Array(W * H * 4), B = new Float32Array(W * H * 4);
    for (let i = 0; i < nb; i++) {
      A[i * 4] = attr.z[i]; A[i * 4 + 1] = attr.h[i]; A[i * 4 + 2] = Math.min(attr.tc[i], 2500) / 100; A[i * 4 + 3] = attr.s[i];
      B[i * 4] = Math.min(attr.tl[i], 2500) / 100; B[i * 4 + 1] = attr.arr[i]; B[i * 4 + 2] = attr.flags[i]; B[i * 4 + 3] = attr.year[i];
    }
    this.bldTex = { A: mk(A, W, H, THREE.RGBAFormat, THREE.FloatType, THREE.NearestFilter), B: mk(B, W, H, THREE.RGBAFormat, THREE.FloatType, THREE.NearestFilter), size: new THREE.Vector2(W, H) };
  }

  // ------------------------------------------------------------------------- scene objects
  gridGeometry(step) {
    const nx = Math.floor(this.Wm / step) + 1, nz = Math.floor(this.Hm / step) + 1;
    const pos = new Float32Array(nx * nz * 3);
    for (let j = 0, k = 0; j < nz; j++) for (let i = 0; i < nx; i++, k += 3) {
      pos[k] = -this.Wm / 2 + i * step; pos[k + 2] = -this.Hm / 2 + j * step;
    }
    const idx = new Uint32Array((nx - 1) * (nz - 1) * 6);
    let o = 0;
    for (let j = 0; j < nz - 1; j++) for (let i = 0; i < nx - 1; i++) {
      const a = j * nx + i, b = a + 1, c = a + nx, d = c + 1;
      idx[o++] = a; idx[o++] = c; idx[o++] = b; idx[o++] = b; idx[o++] = c; idx[o++] = d;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setIndex(new THREE.BufferAttribute(idx, 1));
    return geo;
  }

  mat(vs, fs, uniforms = {}, opts = {}) {
    return new THREE.ShaderMaterial({ vertexShader: vs, fragmentShader: fs, uniforms: Object.assign({}, this.shared, uniforms), ...opts });
  }

  buildSky() {
    const geo = new THREE.PlaneGeometry(2, 2);
    this.skyU = {
      uInvProj: { value: new THREE.Matrix4() }, uCamWorld: { value: new THREE.Matrix4() },
      uSkyTop: { value: new THREE.Vector3() }, uSkyMid: { value: new THREE.Vector3() }, uSkyHorizon: { value: new THREE.Vector3() }, uNight: { value: 1 },
    };
    this.sky = new THREE.Mesh(geo, this.mat(S.skyVS, S.skyFS, this.skyU, { depthWrite: false, depthTest: false }));
    this.sky.frustumCulled = false; this.sky.renderOrder = -10;
    this.scene.add(this.sky);
  }

  buildTerrain() {
    this.terrainGeo = this.gridGeometry(15);
    this.terrainU = {
      uStreetCol: { value: new THREE.Vector3() }, uParkCol: { value: new THREE.Vector3() }, uCanalCol: { value: new THREE.Vector3() },
      uContourCol: { value: new THREE.Vector3() }, uContour: { value: 1 },
    };
    this.terrainMat = this.mat(S.terrainVS, S.terrainFS, this.terrainU);
    this.terrainPickMat = this.mat(S.terrainVS, S.terrainFS, this.terrainU, { defines: { PICK: 1 } });
    this.terrain = new THREE.Mesh(this.terrainGeo, this.terrainMat);
    this.terrain.frustumCulled = false; this.terrain.renderOrder = 0;
    this.scene.add(this.terrain);
  }

  buildWater() {
    this.waterU = {
      uShallow: { value: new THREE.Vector3() }, uDeep: { value: new THREE.Vector3() }, uRiver: { value: new THREE.Vector3() },
      uRiverDeep: { value: new THREE.Vector3() }, uSkyRefl: { value: new THREE.Vector3() }, uHorizon: { value: new THREE.Vector3() }, uGlow: { value: 1 },
    };
    this.waterGeo = this.gridGeometry(20);
    this.water = new THREE.Mesh(this.waterGeo, this.mat(S.waterVS, S.waterFS, this.waterU, { transparent: true, depthWrite: false }));
    this.water.frustumCulled = false; this.water.renderOrder = 3;
    this.scene.add(this.water);
  }

  async enablePPRI(ppri) {
    if (this.ppri) return;
    const g = this.data.meta.grid;
    const mk = (arr, fmt) => { const t = new THREE.DataTexture(arr, g.w, g.h, fmt, THREE.UnsignedByteType); t.minFilter = t.magFilter = THREE.LinearFilter; t.generateMipmaps = false; t.needsUpdate = true; return t; };
    this.ppriU = {
      tPpriA: { value: mk(ppri.a, THREE.RGBAFormat) }, tPpriB: { value: mk(ppri.b, THREE.RGFormat) },
      uBC: { value: new THREE.Vector3() }, uBS: { value: new THREE.Vector3() }, uR: { value: new THREE.Vector3() }, uV: { value: new THREE.Vector3() },
      uOpacity: { value: 1 },
    };
    this.ppri = new THREE.Mesh(this.terrainGeo, this.mat(S.ppriVS, S.ppriFS, this.ppriU, { transparent: true, depthWrite: false }));
    this.ppri.frustumCulled = false; this.ppri.renderOrder = 4; this.ppri.visible = false;
    this.scene.add(this.ppri);
    this.applyThemeToPPRI();
  }

  buildLines() {
    const sub = (pts, maxLen = 30) => {
      const out = [];
      for (let i = 0; i < pts.length - 1; i++) {
        const [x0, z0] = pts[i], [x1, z1] = pts[i + 1];
        const n = Math.max(1, Math.ceil(Math.hypot(x1 - x0, z1 - z0) / maxLen));
        for (let k = 0; k < n; k++) {
          const a = k / n, b = (k + 1) / n;
          out.push(x0 + (x1 - x0) * a, 0, z0 + (z1 - z0) * a, x0 + (x1 - x0) * b, 0, z0 + (z1 - z0) * b);
        }
      }
      return out;
    };
    const mkLines = (polylines, uniforms, order) => {
      const arr = [];
      for (const pl of polylines) arr.push(...sub(pl));
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(arr), 3));
      const m = new THREE.LineSegments(geo, this.mat(S.lineVS, S.lineFS, uniforms, { transparent: true, depthWrite: false }));
      m.frustumCulled = false; m.renderOrder = order;
      this.scene.add(m);
      return m;
    };
    const arrLines = [];
    for (const a of this.data.meta.arrondissements) arrLines.push(...a.outline);
    this.arrU = { uLineCol: { value: new THREE.Vector3() }, uLineAlpha: { value: 0.55 } };
    this.arrLines = mkLines(arrLines, this.arrU, 5);
    this.domU = { uLineCol: { value: new THREE.Vector3() }, uLineAlpha: { value: 0.95 } };
    this.domLine = mkLines(this.data.meta.domain, this.domU, 5);
  }

  buildStations() {
    const st = this.data.stations;
    const n = st.length;
    const iPos = new Float32Array(n * 3), iThr = new Float32Array(n * 4);
    st.forEach((s, i) => {
      iPos[i * 3] = s.x; iPos[i * 3 + 1] = s.ngf; iPos[i * 3 + 2] = s.z;
      iThr[i * 4] = Math.min(s.tc, 2500) / 100; iThr[i * 4 + 1] = Math.min(s.tl, 2500) / 100; iThr[i * 4 + 2] = modeId(s.modes); iThr[i * 4 + 3] = i;
      s.mode = modeId(s.modes);
    });
    this.stU = { uViewport: { value: new THREE.Vector2(1, 1) }, uHoverSt: { value: -1 }, uSelectedSt: { value: -1 }, uPoleH: { value: 60 }, uStationDim: { value: 0 } };
    // sprites
    const quad = new THREE.InstancedBufferGeometry();
    quad.setAttribute('position', new THREE.BufferAttribute(new Float32Array([-1, -1, 0, 1, -1, 0, 1, 1, 0, -1, 1, 0]), 3));
    quad.setIndex([0, 1, 2, 0, 2, 3]);
    quad.setAttribute('iPos', new THREE.InstancedBufferAttribute(iPos, 3));
    quad.setAttribute('iThr', new THREE.InstancedBufferAttribute(iThr, 4));
    quad.instanceCount = n;
    this.stationSprites = new THREE.Mesh(quad, this.mat(S.stationVS, S.stationFS, this.stU, { transparent: true, depthWrite: false, depthTest: false }));
    this.stationSprites.frustumCulled = false; this.stationSprites.renderOrder = 8;
    // poles
    const pole = new THREE.InstancedBufferGeometry();
    pole.setAttribute('position', new THREE.BufferAttribute(new Float32Array([0, 0, 0, 0, 1, 0]), 3));
    pole.setAttribute('iPos', new THREE.InstancedBufferAttribute(iPos, 3));
    pole.setAttribute('iThr', new THREE.InstancedBufferAttribute(iThr, 4));
    pole.instanceCount = n;
    this.stationPoles = new THREE.LineSegments(pole, this.mat(S.poleVS, S.poleFS, this.stU, { transparent: true, depthWrite: false }));
    this.stationPoles.frustumCulled = false; this.stationPoles.renderOrder = 7;
    this.stationGroup = new THREE.Group();
    this.stationGroup.add(this.stationPoles, this.stationSprites);
    this.scene.add(this.stationGroup);
    this.stationPos = st.map((s) => new THREE.Vector3(s.x, 0, s.z));
  }

  // ------------------------------------------------------------------------- buildings
  /** Triangulates all chunks in workers; resolves when every chunk has been added. */
  async loadBuildings(onProgress) {
    const { geom } = this.data.buildings;
    const nChunks = geom.nChunks;
    // prefix sums: rings and vertices per building
    const ringStart = new Uint32Array(geom.n + 1), vertStart = new Uint32Array(geom.n + 1);
    {
      let r = 0, v = 0;
      for (let b = 0; b < geom.n; b++) {
        ringStart[b] = r; vertStart[b] = v;
        const rc = geom.ringCount[b];
        for (let k = 0; k < rc; k++) v += geom.ringLen[r + k];
        r += rc;
      }
      ringStart[geom.n] = r; vertStart[geom.n] = v;
    }
    const uniforms = {
      tBldA: { value: this.bldTex.A }, tBldB: { value: this.bldTex.B }, uBldTex: { value: this.bldTex.size },
      uWallCol: { value: new THREE.Vector3() }, uRoofCol: { value: new THREE.Vector3() }, uWindowCol: { value: new THREE.Vector3() }, uWindowStrength: { value: 0 },
      uRamp: { value: DEPTH_RAMP.map((h) => V3(col(h))) }, uWaterTint: { value: new THREE.Vector3() },
      uHover: { value: -1 }, uSelected: { value: -1 }, uDim: { value: 0 },
    };
    this.bldU = uniforms;
    this.bldMat = this.mat(S.buildingVS, S.buildingFS, uniforms, { side: THREE.DoubleSide });
    this.bldPickMat = this.mat(S.buildingVS, S.buildingFS, uniforms, { side: THREE.DoubleSide, defines: { PICK: 1 } });
    this.applyTheme();

    const nWorkers = Math.max(2, Math.min(6, (navigator.hardwareConcurrency || 4) - 1));
    const workers = Array.from({ length: nWorkers }, () => new Worker(new URL('./workers/buildings.worker.js', import.meta.url), { type: 'module' }));
    let next = 0, done = 0;
    this.group = new THREE.Group(); this.group.renderOrder = 1; this.scene.add(this.group);
    return new Promise((resolve, reject) => {
      const post = (w) => {
        if (next >= nChunks) return;
        const c = next++;
        const b0 = geom.chunkBounds[c], b1 = geom.chunkBounds[c + 1];
        const r0 = ringStart[b0], r1 = ringStart[b1], v0 = vertStart[b0], v1 = vertStart[b1];
        w.postMessage({
          chunk: c, b0, nB: b1 - b0,
          ringCount: geom.ringCount.slice(b0, b1), ringLen: geom.ringLen.slice(r0, r1),
          origin: geom.origin.slice(b0 * 2, b1 * 2), xy: geom.xy.slice(v0 * 2, v1 * 2), Q: 10,
        });
      };
      workers.forEach((w) => {
        w.onerror = (e) => reject(e);
        w.onmessage = (e) => {
          this.addChunk(e.data);
          done++;
          onProgress?.(done / nChunks);
          if (done === nChunks) { workers.forEach((x) => x.terminate()); resolve(); } else post(w);
        };
        post(w);
      });
    });
  }

  addChunk({ pos, index, bounds }) {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setIndex(new THREE.BufferAttribute(index, 1));
    const cx = (bounds[0] + bounds[1]) / 2, cz = (bounds[2] + bounds[3]) / 2;
    const r = Math.hypot(bounds[1] - bounds[0], bounds[3] - bounds[2]) / 2;
    geo.boundingSphere = new THREE.Sphere(new THREE.Vector3(cx, 60, cz), r + 400);
    const mesh = new THREE.Mesh(geo, this.bldMat);
    mesh.renderOrder = 1;
    this.group.add(mesh);
    this.buildingMeshes.push(mesh);
  }

  // ------------------------------------------------------------------------- theme / state
  setTheme(name) {
    this.themeName = name; this.theme = THEMES[name];
    document.documentElement.dataset.theme = this.theme.css;
    this.applyTheme();
  }

  applyTheme() {
    const t = this.theme, s = this.shared;
    s.uFogCol.value.set(...col(t.fog)); s.uFogDensity.value = t.fogDensity;
    s.uSunCol.value.set(...col(t.sun).map((v) => v * t.sunStrength));
    s.uSunDir.value.set(...t.sunDir).normalize();
    s.uAmbSky.value.set(...col(t.ambSky)); s.uAmbGround.value.set(...col(t.ambGround)); s.uAmbient.value = t.ambient;
    s.uExposure.value = name_exposure[this.themeName];
    this.skyU.uSkyTop.value.set(...col(t.skyTop)); this.skyU.uSkyMid.value.set(...col(t.skyMid)); this.skyU.uSkyHorizon.value.set(...col(t.skyHorizon));
    this.skyU.uNight.value = this.themeName === 'night' ? 1 : 0;
    const tu = this.terrainU;
    tu.uStreetCol.value.set(...col(t.street)); tu.uParkCol.value.set(...col(t.park)); tu.uCanalCol.value.set(...col(t.canal)); tu.uContourCol.value.set(...col(t.contour));
    const w = this.waterU;
    w.uShallow.value.set(...col(t.waterShallow)); w.uDeep.value.set(...col(t.waterDeep)); w.uRiver.value.set(...col(t.river)); w.uRiverDeep.value.set(...col(t.riverDeep));
    w.uSkyRefl.value.set(...col(t.sky)); w.uHorizon.value.set(...col(t.skyHorizon)); w.uGlow.value = t.glow;
    this.arrU.uLineCol.value.set(...col(this.themeName === 'night' ? '#7fa6c8' : '#51606d'));
    this.domU.uLineCol.value.set(...col(this.themeName === 'night' ? '#9fe0ff' : '#1d3b52'));
    if (this.bldU) {
      const b = this.bldU;
      b.uWallCol.value.set(...col(t.wall)); b.uRoofCol.value.set(...col(t.roof)); b.uWindowCol.value.set(...col(t.window)); b.uWindowStrength.value = t.windowStrength;
      b.uWaterTint.value.set(...col(t.waterDeep)).multiplyScalar(1.6);
    }
    this.applyThemeToPPRI();
  }

  applyThemeToPPRI() {
    if (!this.ppriU) return;
    const p = this.theme.ppri;
    this.ppriU.uBC.value.set(...col(p.bc)); this.ppriU.uBS.value.set(...col(p.bs)); this.ppriU.uR.value.set(...col(p.r)); this.ppriU.uV.value.set(...col(p.v));
  }

  setLevel(L) { this.shared.uLevel.value = L; }
  setMode(m) { this.shared.uMode.value = m; }
  setExag(x) { this.shared.uExag.value = x; this.exag = x; }
  setPPRI(on) { if (this.ppri) this.ppri.visible = on; this.dimForOverlay(on); }
  dimForOverlay(on) { if (this.bldU) this.bldU.uDim.value = on ? 0.25 : 0; }
  setStations(on) { this.stationGroup.visible = on; }
  setArrLines(on) { this.arrLines.visible = on; }
  setContours(on) { this.terrainU.uContour.value = on ? 1 : 0; }
  setBuildingsVisible(on) { if (this.group) this.group.visible = on; }

  // ------------------------------------------------------------------------- camera
  setupControls() {
    const c = this.controls = new OrbitControls(this.camera, this.canvas);
    c.enableDamping = true; c.dampingFactor = 0.09; c.zoomToCursor = true; c.screenSpacePanning = false;
    c.minDistance = 60; c.maxDistance = 24000; c.maxPolarAngle = 1.50; c.minPolarAngle = 0.05;
    c.rotateSpeed = 0.6; c.panSpeed = 0.9; c.zoomSpeed = 0.9;
    c.mouseButtons = { LEFT: THREE.MOUSE.ROTATE, MIDDLE: THREE.MOUSE.DOLLY, RIGHT: THREE.MOUSE.PAN };
    c.addEventListener('start', () => { this.flight = null; this.emit('interact'); });
    this.exag = 1;
    this.setView({ x: 400, z: -250, dist: 13000, az: 0.35, polar: 1.0 });
  }

  /** az: radians, 0 = camera south of target looking north; polar: angle from vertical. */
  setView({ x, z, dist, az, polar }) {
    const y = 0;
    this.controls.target.set(x, y, z);
    const sp = Math.sin(polar), cp = Math.cos(polar);
    this.camera.position.set(x + dist * sp * Math.sin(az), y + dist * cp, z + dist * sp * Math.cos(az));
    this.camera.lookAt(this.controls.target);
    this.controls.update();
  }

  currentView() {
    const t = this.controls.target, p = this.camera.position;
    const d = p.clone().sub(t); const dist = d.length();
    return { x: t.x, z: t.z, dist, az: Math.atan2(d.x, d.z), polar: Math.acos(Math.min(1, Math.max(-1, d.y / dist))) };
  }

  flyTo(view, ms = 2400) {
    const a = this.currentView();
    let da = view.az - a.az; da = Math.atan2(Math.sin(da), Math.cos(da));
    this.flight = { a, b: { ...view }, da, t0: performance.now(), ms };
  }

  stepFlight() {
    const f = this.flight; if (!f) return;
    let k = Math.min(1, (performance.now() - f.t0) / f.ms);
    const e = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
    // arc: pull back while travelling so the move reads as a flight
    const arc = Math.sin(Math.PI * e) * Math.min(1.0, Math.hypot(f.b.x - f.a.x, f.b.z - f.a.z) / 6000) * 0.55;
    const dist = Math.exp(Math.log(f.a.dist) * (1 - e) + Math.log(f.b.dist) * e) * (1 + arc);
    this.setView({
      x: f.a.x + (f.b.x - f.a.x) * e, z: f.a.z + (f.b.z - f.a.z) * e, dist,
      az: f.a.az + f.da * e, polar: f.a.polar + (f.b.polar - f.a.polar) * e,
    });
    if (k >= 1) this.flight = null;
  }

  // ------------------------------------------------------------------------- picking / projection
  project(x, y, z, out = new THREE.Vector3()) {
    out.set(x, y, z).project(this.camera);
    return { x: (out.x * 0.5 + 0.5) * this.w, y: (-out.y * 0.5 + 0.5) * this.h, visible: out.z < 1 && out.z > -1 };
  }

  groundY(x, z) {
    // CPU copy of the ground height (nearest cell) in scene units, used to anchor labels
    const g = this.data.meta.grid;
    const i = Math.min(g.w - 1, Math.max(0, Math.floor((x + this.Wm / 2) / g.cell)));
    const j = Math.min(g.h - 1, Math.max(0, Math.floor((z + this.Hm / 2) / g.cell)));
    return (this.data.ground[j * g.w + i] / 100 + g.groundBase - Y_REF) * (this.exag || 1);
  }

  pickBuilding(cx, cy) {
    if (!this.group || !this.group.visible) return -1;
    const rect = this.canvas.getBoundingClientRect();
    const x = (cx - rect.left), y = (cy - rect.top);
    if (x < 0 || y < 0 || x >= rect.width || y >= rect.height) return -1;
    const r = this.renderer;
    const prevVis = [this.sky.visible, this.water.visible, this.stationGroup.visible, this.arrLines.visible, this.domLine.visible, this.ppri?.visible];
    this.sky.visible = this.water.visible = this.stationGroup.visible = this.arrLines.visible = this.domLine.visible = false;
    if (this.ppri) this.ppri.visible = false;
    this.terrain.material = this.terrainPickMat;
    for (const m of this.buildingMeshes) m.material = this.bldPickMat;
    this.camera.setViewOffset(rect.width, rect.height, Math.floor(x), Math.floor(y), 1, 1);
    r.setRenderTarget(this.pickTarget);
    r.setClearColor(0x000000, 0); r.clear();
    r.render(this.scene, this.camera);
    r.readRenderTargetPixels(this.pickTarget, 0, 0, 1, 1, this.pickBuf);
    r.setRenderTarget(null); r.setClearColor(0x000000, 1);
    this.camera.clearViewOffset();
    this.terrain.material = this.terrainMat;
    for (const m of this.buildingMeshes) m.material = this.bldMat;
    [this.sky.visible, this.water.visible, this.stationGroup.visible, this.arrLines.visible, this.domLine.visible] = prevVis;
    if (this.ppri) this.ppri.visible = prevVis[5];
    const v = this.pickBuf[0] + this.pickBuf[1] * 256 + this.pickBuf[2] * 65536;
    return v - 1;
  }

  pickStation(cx, cy, radius = 16) {
    if (!this.stationGroup.visible) return -1;
    const rect = this.canvas.getBoundingClientRect();
    const px = cx - rect.left, py = cy - rect.top;
    let best = -1, bd = radius * radius;
    const v = new THREE.Vector3();
    const poleH = this.stU.uPoleH.value;
    this.data.stations.forEach((s, i) => {
      const y = (s.ngf - Y_REF) * (this.exag || 1);
      const dist = this.camera.position.distanceTo(v.set(s.x, y, s.z));
      const h = poleH * (0.35 + 0.65 * Math.min(1, dist / 2500));
      const p = this.project(s.x, y + h, s.z);
      if (!p.visible) return;
      const d = (p.x - px) ** 2 + (p.y - py) ** 2;
      if (d < bd) { bd = d; best = i; }
    });
    return best;
  }

  // ------------------------------------------------------------------------- frame
  resize() {
    const w = this.canvas.clientWidth || window.innerWidth, h = this.canvas.clientHeight || window.innerHeight;
    this.w = w; this.h = h;
    this.renderer.setPixelRatio(this.pr);
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h; this.camera.updateProjectionMatrix();
    this.stU.uViewport.value.set(w, h);
  }

  adaptResolution(dt) {
    if (this.opts.fixedDpr) return;
    this.frameTimes.push(dt);
    if (this.frameTimes.length < 40) return;
    const avg = this.frameTimes.reduce((a, b) => a + b, 0) / this.frameTimes.length;
    this.frameTimes.length = 0;
    let pr = this.pr;
    if (avg > 0.036 && pr > 0.6) pr = Math.max(0.6, pr * 0.85);
    else if (avg < 0.015 && pr < this.maxPR) pr = Math.min(this.maxPR, pr * 1.12);
    if (Math.abs(pr - this.pr) > 0.01) { this.pr = pr; this.resize(); }
  }

  render() {
    const dt = this.clock.getDelta();
    this.shared.uTime.value += dt;
    this.stepFlight();
    this.controls.update();
    // keep the target above the map and the camera clear of the ground
    const t = this.controls.target;
    const hx = this.Wm / 2 - 300, hz = this.Hm / 2 - 300;
    t.x = Math.max(-hx, Math.min(hx, t.x)); t.z = Math.max(-hz, Math.min(hz, t.z));
    const dist = this.camera.position.distanceTo(t);
    this.camera.near = Math.max(2, Math.min(300, dist * 0.015)); this.camera.far = 90000;
    this.camera.updateProjectionMatrix();
    this.skyU.uInvProj.value.copy(this.camera.projectionMatrixInverse);
    this.skyU.uCamWorld.value.copy(this.camera.matrixWorld);
    this.stU.uPoleH.value = 70;
    this.renderer.render(this.scene, this.camera);
    this.adaptResolution(dt);
    this.emit('frame', dt);
  }

  start() {
    const loop = () => { requestAnimationFrame(loop); if (!document.hidden) this.render(); };
    loop();
  }
}

const name_exposure = { night: 1.25, day: 1.05 };

