import { HISTORIC, MAX_LEVEL, lineColor, MODE_LABEL, DEPTH_RAMP, DEPTH_STOPS, Y_REF } from './config.js';
import { t, nf, setLang, getLang } from './i18n.js';

const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const fmtL = (v) => v.toFixed(2);

const VIEWS = [
  { key: 'overview', en: 'Overview', fr: "Vue d'ensemble", view: { x: 250, z: 500, dist: 10800, az: 0.22, polar: 1.0 } },
  { key: 'cite', en: 'Île de la Cité', fr: 'Île de la Cité', view: { x: 760, z: 420, dist: 1500, az: -0.55, polar: 1.12 } },
  { key: 'austerlitz', en: 'Austerlitz · Gare de Lyon', fr: 'Austerlitz · Gare de Lyon', view: { x: 2650, z: 1750, dist: 2500, az: -0.75, polar: 1.1 } },
  { key: 'concorde', en: 'Concorde · Orsay', fr: 'Concorde · Orsay', view: { x: -800, z: -250, dist: 2100, az: 0.55, polar: 1.1 } },
  { key: 'eiffel', en: 'Tour Eiffel · Grenelle', fr: 'Tour Eiffel · Grenelle', view: { x: -3300, z: 650, dist: 2900, az: 0.9, polar: 1.05 } },
  { key: 'javel', en: 'Javel · Auteuil', fr: 'Javel · Auteuil', view: { x: -5000, z: 1450, dist: 3400, az: 0.95, polar: 1.0 } },
];

export function initUI(city, data, opts = {}) {
  const meta = data.meta, stats = data.stats, NL = meta.nl;
  const stations = data.stations;
  const state = { level: 0, mode: 0, playing: false, speed: 0.6, theme: city.themeName, selSt: -1, selB: -1, chartTable: false, stationsOpen: false, labels: true, ppriLoaded: false };

  // -------------------------------------------------------------------------- i18n
  function applyI18n() {
    $$('[data-i]').forEach((el) => { const v = t(el.dataset.i); if (typeof v === 'string') el.textContent = v; });
    $$('[data-iph]').forEach((el) => { el.placeholder = t(el.dataset.iph); });
    $('#aboutBody').innerHTML = t('aboutBody');
    $('#aboutCredits').textContent = t('credits');
    $('#credits').textContent = t('credits');
    $('#slider').setAttribute('aria-label', t('levelAria'));
    $('#modeHint').textContent = state.mode ? t('modeAnyHint') : t('modeConnectedHint');
    $('#chartToggle').textContent = state.chartTable ? t('chartView') : t('tableView');
    $('#playLabel').textContent = state.playing ? t('pause') : t('play');
    $('#resetBtn').textContent = t('reset');
    $('#modeSeg [data-mode="0"]').textContent = t('modeConnected'); $('#modeSeg [data-mode="1"]').textContent = t('modeAny');
    buildViewChips(); buildMarkers(); buildStationList(); rebuildLabels(); buildArrChart(); update(true);
  }

  // -------------------------------------------------------------------------- viewpoints
  function buildViewChips() {
    const box = $('#viewChips'); box.innerHTML = '';
    for (const v of VIEWS) {
      const b = document.createElement('button'); b.textContent = v[getLang()];
      b.onclick = () => city.flyTo(v.view, 2600);
      box.appendChild(b);
    }
  }

  // -------------------------------------------------------------------------- gauge
  const slider = $('#slider'), track = $('#track');
  function buildTicks() {
    const box = $('#ticks'); box.innerHTML = '';
    for (let i = 0; i <= MAX_LEVEL; i++) { const s = document.createElement('span'); s.style.left = (i / MAX_LEVEL) * 100 + '%'; s.textContent = i; box.appendChild(s); }
  }
  function buildMarkers() {
    const box = $('#markers'); box.innerHTML = '';
    const side = { 2018: 'l', 2016: 'r', 1955: 'c', 1910: 'c' };
    for (const h of HISTORIC) {
      const m = document.createElement('div'); m.className = 'marker ' + side[h.year]; m.dataset.level = h.level;
      m.style.left = (h.level / MAX_LEVEL) * 100 + '%';
      const b = document.createElement('button');
      b.innerHTML = `<b>${h.year}</b>${nf(h.level, 2)}`;
      b.title = t('markerTitle')(h.year, nf(h.level, 2));
      b.onclick = () => animateTo(h.level, 1800);
      m.appendChild(b); box.appendChild(m);
    }
  }
  function drawArea() {
    const svg = $('#areaSvg'); const mode = state.mode;
    const base = mode * 3 * NL; const max = stats.area[base + 1000] || 1;
    let d = 'M0 40';
    for (let c = 0; c <= 1000; c += 5) d += ` L${c} ${(40 - (stats.area[base + c] / max) * 38).toFixed(2)}`;
    d += ' L1000 40 Z';
    svg.setAttribute('viewBox', '0 0 1000 40');
    svg.innerHTML = `<defs><linearGradient id="ag" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".55"/><stop offset="1" stop-color="var(--accent)" stop-opacity=".04"/></linearGradient>
      <clipPath id="clipL"><rect id="clipRect" x="0" y="-2" width="0" height="44"/></clipPath></defs>
      <path d="${d}" fill="var(--bar-bg)" stroke="var(--faint)" stroke-width="1" vector-effect="non-scaling-stroke"/>
      <path d="${d}" fill="url(#ag)" stroke="var(--accent)" stroke-width="1.5" vector-effect="non-scaling-stroke" clip-path="url(#clipL)"/>`;
    $('#clipRect')?.setAttribute('width', state.level * 100);
  }

  let rafPending = false;
  function setLevel(v, fromSlider = false) {
    state.level = clamp(v, 0, MAX_LEVEL);
    city.setLevel(state.level);
    if (!fromSlider) slider.value = Math.round(state.level * 100);
    slider.style.setProperty('--v', state.level / MAX_LEVEL);
    if (!rafPending) { rafPending = true; requestAnimationFrame(() => { rafPending = false; update(); }); }
  }
  let anim = null;
  function animateTo(target, ms = 1600) {
    stopPlay();
    anim = { from: state.level, to: target, t0: performance.now(), ms: Math.max(300, ms * Math.min(1, 0.4 + Math.abs(target - state.level) / 5)) };
  }
  function stepAnim(now) {
    if (!anim) return;
    const k = Math.min(1, (now - anim.t0) / anim.ms);
    const e = 1 - Math.pow(1 - k, 3);
    setLevel(anim.from + (anim.to - anim.from) * e);
    if (k >= 1) anim = null;
  }
  slider.addEventListener('input', () => { anim = null; stopPlay(); setLevel(slider.value / 100, true); });
  $$('.steppers button').forEach((b) => b.addEventListener('click', () => { anim = null; stopPlay(); setLevel(Math.round(state.level * 100 + +b.dataset.step) / 100); }));

  // playback with a short pause on each historic level
  let linger = 0, lastCross = -1;
  function startPlay() {
    if (state.level >= MAX_LEVEL - 0.005) setLevel(0);
    state.playing = true; lastCross = state.level; $('#playLabel').textContent = t('pause');
    $('#playIcon').setAttribute('d', 'M6 4h4v16H6zM14 4h4v16h-4z');
  }
  function stopPlay() { state.playing = false; $('#playLabel').textContent = t('play'); $('#playIcon').setAttribute('d', 'M7 4.5v15l12-7.5z'); }
  $('#playBtn').onclick = () => (state.playing ? stopPlay() : (anim = null, startPlay()));
  $('#resetBtn').onclick = () => { stopPlay(); animateTo(0, 1200); };
  $$('#speedSeg button').forEach((b) => (b.onclick = () => { state.speed = +b.dataset.speed; $$('#speedSeg button').forEach((x) => x.classList.toggle('on', x === b)); }));

  function toast(msg) {
    const el = $('#toast'); el.textContent = msg; el.classList.add('show');
    clearTimeout(toast.t); toast.t = setTimeout(() => el.classList.remove('show'), 2300);
  }
  let lastT = performance.now();
  function tick(now) {
    const dt = Math.min(0.1, (now - lastT) / 1000); lastT = now;
    stepAnim(now);
    if (state.playing) {
      if (linger > 0) linger -= dt;
      else {
        const prev = state.level;
        const next = Math.min(MAX_LEVEL, prev + state.speed * dt);
        const hit = HISTORIC.find((h) => prev < h.level && next >= h.level);
        if (hit) { setLevel(hit.level); linger = 1.6; toast(`${t('levelToastLabel')} · ${hit.year} · +${nf(hit.level, 2)} m`); }
        else setLevel(next);
        if (next >= MAX_LEVEL) stopPlay();
      }
    }
    requestAnimationFrame(tick);
  }

  // -------------------------------------------------------------------------- statistics
  const totalB = data.buildings.geom.n;
  const landHa = meta.counts.landHa;
  const stModes = ['METRO', 'RER', 'TRAIN', 'TRAMWAY'];
  const stTotals = Object.fromEntries(stModes.map((m) => [m, stations.filter((s) => s.modes.includes(m)).length]));
  const thr = (s) => (state.mode ? s.tl : s.tc) / 100;
  const arrTotals = new Array(21).fill(0);
  { const arr = data.buildings.attr.arr; for (let i = 0; i < arr.length; i++) arrTotals[arr[i]]++; }
  const arrMax = [0, 1].map((m) => { let mx = 1; for (let a = 1; a <= 20; a++) mx = Math.max(mx, stats.buildings[(m * 21 + a) * NL + 1000]); return mx; });

  function stationCounts(L) {
    const c = { flooded: 0, alert: 0, byMode: { METRO: 0, RER: 0, TRAIN: 0, TRAMWAY: 0 } };
    for (const s of stations) {
      const m = thr(s) - L;
      if (m <= 0.0005) { c.flooded++; for (const md of s.modes) if (md in c.byMode) c.byMode[md]++; } else if (m <= 0.5) c.alert++;
    }
    return c;
  }
  const dmaxAt = (L) => {
    const x = clamp(L * 10, 0, 100), i = Math.floor(x), f = x - i, b = state.mode * 101;
    return stats.dmax[b + i] * (1 - f) + stats.dmax[b + Math.min(100, i + 1)] * f;
  };

  const el = { area: $('#vArea'), sArea: $('#sArea'), bld: $('#vBld'), sBld: $('#sBld'), st: $('#vSt'), sSt: $('#sSt'), pills: $('#stPills'), depth: $('#vDepth'), sDepth: $('#sDepth') };
  function update(force = false) {
    const L = state.level, idx = clamp(Math.round(L * 100), 0, 1000), m = state.mode;
    // gauge text
    $('#levelNum').textContent = fmtL(L).replace('.', getLang() === 'fr' ? ',' : '.');
    $('#ngf').textContent = t('gaugeNgf')(nf(meta.hydro.gaugeZeroNgf + L, 2));
    $('#clipRect')?.setAttribute('width', L * 100);
    // comparison with history
    const near = HISTORIC.find((h) => Math.abs(h.level - L) < 0.005);
    const next = HISTORIC.find((h) => h.level > L + 0.005);
    let cmp;
    if (L < 0.02) cmp = t('normal');
    else if (near) cmp = t('cmpEqual')(near.year);
    else if (next) cmp = t('cmpNext')(nf(next.level - L, 2), next.year, nf(next.level, 2));
    else cmp = t('cmpBeyond1910')(nf(L - 8.62, 2));
    const cEl = $('#compare'); cEl.textContent = cmp; cEl.classList.toggle('hot', L >= 5.84);
    $$('.marker').forEach((mk) => mk.classList.toggle('active', Math.abs(+mk.dataset.level - L) < 0.005));
    $('#pinLevel') && ($('#pinLevel').textContent = `+${fmtL(L)} m`);
    // counters
    const ha = stats.area[(m * 3) * NL + idx];
    el.area.textContent = nf(ha, ha >= 100 ? 0 : 1);
    el.sArea.textContent = ha < 0.05 ? t('areaNote') : t('areaShare')(nf((ha / landHa) * 100, 1));
    const nb = stats.buildings[(m * 21) * NL + idx];
    el.bld.textContent = nf(nb);
    el.sBld.textContent = t('buildingsShare')(nf((nb / totalB) * 100, 1), nf(totalB));
    const sc = stationCounts(L);
    el.st.textContent = sc.flooded;
    el.sSt.textContent = `${t('stationsOf')(stations.length)}${sc.alert ? ' · ' + sc.alert + ' ' + t('stateAlert').toLowerCase() : ''}`;
    el.pills.innerHTML = stModes.map((md) => `<span class="pill ${sc.byMode[md] ? 'hot' : ''}">${MODE_LABEL[md]} ${sc.byMode[md]}/${stTotals[md]}</span>`).join('');
    const dm = dmaxAt(L);
    el.depth.textContent = nf(dm, 1);
    el.sDepth.textContent = dm < 0.05 ? '—' : `≈ ${nf(dm / 3.1, 1)} ${getLang() === 'fr' ? 'étages' : 'storeys'}`;
    updateArrChart(idx);
    if (state.stationsOpen) updateStationList();
    scheduleHash();
  }

  // -------------------------------------------------------------------------- arrondissement chart
  const arrRows = [];
  function buildArrChart() {
    const box = $('#arrChart'); box.innerHTML = ''; arrRows.length = 0;
    for (let a = 1; a <= 20; a++) {
      const r = document.createElement('div'); r.className = 'arr-row';
      r.innerHTML = `<span class="n">${t('arrLabel')(a)}</span><span class="bar"><i></i></span><span class="v">0</span>`;
      r.addEventListener('pointerenter', (e) => showArrTip(a, e)); r.addEventListener('pointermove', moveTip); r.addEventListener('pointerleave', hideTip);
      r.addEventListener('click', () => { const am = meta.arrondissements[a - 1]; city.flyTo({ x: am.x, z: am.z, dist: 3400, az: 0.2, polar: 1.05 }, 2200); });
      box.appendChild(r); arrRows.push(r);
    }
  }
  function arrStats(a, idx) {
    const m = state.mode;
    return { b: stats.buildings[(m * 21 + a) * NL + idx], ha: stats.areaArr[(m * 21 + a) * NL + idx], tot: arrTotals[a] };
  }
  function updateArrChart(idx) {
    const mx = arrMax[state.mode];
    for (let a = 1; a <= 20; a++) {
      const { b } = arrStats(a, idx); const r = arrRows[a - 1]; if (!r) continue;
      r.firstChild.nextSibling.firstChild.style.width = (b / mx) * 100 + '%';
      r.lastChild.textContent = nf(b); r.classList.toggle('zero', b === 0);
    }
    if (state.chartTable) buildArrTable(idx);
  }
  function buildArrTable(idx) {
    let h = `<table><thead><tr><th>${t('arrCol')}</th><th>${t('bldCol')}</th><th>${t('shareCol')}</th><th>${t('areaCol')}</th></tr></thead><tbody>`;
    for (let a = 1; a <= 20; a++) { const s = arrStats(a, idx); h += `<tr><td>${t('arrLabel')(a)}</td><td>${nf(s.b)}</td><td>${nf((s.b / s.tot) * 100, 1)} %</td><td>${nf(s.ha, 1)}</td></tr>`; }
    $('#arrTable').innerHTML = h + '</tbody></table>';
  }
  $('#chartToggle').onclick = () => {
    state.chartTable = !state.chartTable;
    $('#arrChart').hidden = state.chartTable; $('#arrTable').hidden = !state.chartTable;
    $('#chartToggle').textContent = state.chartTable ? t('chartView') : t('tableView'); update();
  };

  // -------------------------------------------------------------------------- tooltip
  const tip = $('#tooltip');
  let tipPos = { x: 0, y: 0 };
  function placeTip() {
    const w = tip.offsetWidth, h = tip.offsetHeight;
    let x = tipPos.x + 16, y = tipPos.y + 16;
    if (x + w > innerWidth - 8) x = tipPos.x - w - 16;
    if (y + h > innerHeight - 8) y = tipPos.y - h - 16;
    tip.style.left = Math.max(8, x) + 'px'; tip.style.top = Math.max(8, y) + 'px';
  }
  function moveTip(e) { tipPos = { x: e.clientX, y: e.clientY }; placeTip(); }
  function hideTip() { tip.hidden = true; }
  function showTip(html, e) { tip.innerHTML = html; tip.hidden = false; if (e) tipPos = { x: e.clientX, y: e.clientY }; placeTip(); }
  function showArrTip(a, e) {
    const idx = clamp(Math.round(state.level * 100), 0, 1000), s = arrStats(a, idx);
    showTip(`<div class="t-title">${t('arrLabel')(a)} ${t('arrSuffix')}</div><dl><dt>${t('bldCol')}</dt><dd>${nf(s.b)} / ${nf(s.tot)} (${nf((s.b / s.tot) * 100, 0)}%)</dd><dt>${t('areaCol')}</dt><dd>${nf(s.ha, 1)}</dd></dl>`, e);
  }

  function badges(s) {
    const out = [];
    for (const [mode, label] of s.lines) {
      if (mode === 'TRAIN') continue;
      const c = lineColor(mode, label);
      const lum = (parseInt(c.slice(1, 3), 16) * 0.299 + parseInt(c.slice(3, 5), 16) * 0.587 + parseInt(c.slice(5, 7), 16) * 0.114);
      out.push(`<span class="badge ${mode === 'METRO' ? '' : 'sq'}" style="background:${c};color:${lum > 150 ? '#111' : '#fff'}">${mode === 'RER' ? 'RER ' : ''}${label}</span>`);
    }
    if (s.modes.includes('TRAIN')) out.push(`<span class="badge sq" style="background:#8a8f98;color:#fff">${MODE_LABEL.TRAIN}</span>`);
    return `<span class="badges">${out.join('')}</span>`;
  }
  const stateOf = (s) => { const m = thr(s) - state.level; return m <= 0.0005 ? 'flooded' : m <= 0.5 ? 'alert' : 'ok'; };
  function stationTip(i, e) {
    const s = stations[i], st = stateOf(s), T = t('hoverStation'), th = thr(s);
    showTip(`<div class="t-title">${s.name} ${badges(s)}</div><dl><dt>${T.ground}</dt><dd>${nf(s.ngf, 2)} m NGF</dd><dt>${T.from}</dt><dd>${th >= 25 ? '—' : '+' + nf(th, 2) + ' m'}</dd></dl>
      <div class="state ${st}">${st === 'flooded' ? t('stateFlooded') : st === 'alert' ? t('stateAlert') : t('stateOk')}</div>`, e);
  }
  const bStart = (() => { // first vertex of each building, to locate it
    const g = data.buildings.geom; const rs = new Uint32Array(g.n + 1), vs = new Uint32Array(g.n + 1);
    let r = 0, v = 0;
    for (let b = 0; b < g.n; b++) { rs[b] = r; vs[b] = v; for (let k = 0; k < g.ringCount[b]; k++) v += g.ringLen[r + k]; r += g.ringCount[b]; }
    return { rs, vs };
  })();
  function buildingCenter(i) {
    const g = data.buildings.geom, v0 = bStart.vs[i], n = g.ringLen[bStart.rs[i]];
    let sx = 0, sz = 0;
    for (let k = 0; k < n; k++) { sx += (g.origin[2 * i] + g.xy[2 * (v0 + k)]) / 10; sz += -(g.origin[2 * i + 1] + g.xy[2 * (v0 + k) + 1]) / 10; }
    return { x: sx / n, z: sz / n };
  }
  function buildingTip(i, e) {
    const a = data.buildings.attr, T = t('hoverBuilding');
    const th = (state.mode ? a.tl[i] : a.tc[i]) / 100;
    const s = (state.mode ? a.tl[i] : a.tc[i]) / 100;
    const surf = meta.hydro.gaugeZeroNgf + state.level - slopeK(state.level) * a.s[i];
    const wet = th <= state.level + 0.0005;
    const depth = wet ? Math.max(0, surf - a.z[i]) : 0;
    const arr = a.arr[i];
    showTip(`<div class="t-title">${T.title} · ${t('arrLabel')(arr)} ${t('arrSuffix')}</div>
      <dl>${a.year[i] > 1000 ? `<dt>${T.built}</dt><dd>${a.year[i]}</dd>` : ''}<dt>${T.height}</dt><dd>${nf(a.h[i], 0)} m</dd><dt>${T.ground}</dt><dd>${nf(a.z[i], 1)} m NGF</dd>
      <dt>${T.floodsFrom}</dt><dd>${s >= 25 ? T.never : '+' + nf(s, 2) + ' m'}</dd></dl>
      <div class="state ${wet ? 'flooded' : 'ok'}">${wet ? `${T.depthNow} : ${nf(depth, 2)} m` : T.dry}</div>`, e);
  }
  function slopeK(L) { const h = meta.hydro; const x = clamp((L - h.slopeL0) / (h.slopeL1 - h.slopeL0), 0, 1); return h.slopeKm * x * x * (3 - 2 * x); }

  // -------------------------------------------------------------------------- pointer interaction on the map
  const canvas = city.canvas;
  let down = null, hoverTimer = 0, hov = { b: -1, s: -1 };
  canvas.addEventListener('pointerdown', (e) => { down = { x: e.clientX, y: e.clientY, t: performance.now() }; hideTip(); });
  canvas.addEventListener('pointerup', (e) => {
    if (!down) return;
    const moved = Math.hypot(e.clientX - down.x, e.clientY - down.y); down = null;
    if (moved > 5 || e.button !== 0) return;
    const si = city.pickStation(e.clientX, e.clientY);
    if (si >= 0) { selectStation(si, true); return; }
    const bi = city.pickBuilding(e.clientX, e.clientY);
    if (bi >= 0) { state.selB = bi; city.bldU.uSelected.value = bi; const c = buildingCenter(bi); const cur = city.currentView(); city.flyTo({ x: c.x, z: c.z, dist: Math.min(cur.dist, 700), az: cur.az, polar: cur.polar }, 1400); }
    else { state.selB = -1; city.bldU.uSelected.value = -1; selectStation(-1); }
  });
  canvas.addEventListener('pointermove', (e) => {
    if (e.buttons) { hideTip(); return; }
    const ev = { clientX: e.clientX, clientY: e.clientY };
    clearTimeout(hoverTimer);
    hoverTimer = setTimeout(() => {
      const si = city.pickStation(ev.clientX, ev.clientY);
      if (si >= 0) {
        city.stU.uHoverSt.value = si; city.bldU.uHover.value = -1; canvas.style.cursor = 'pointer'; stationTip(si, ev); hov = { b: -1, s: si }; return;
      }
      city.stU.uHoverSt.value = -1;
      const bi = city.pickBuilding(ev.clientX, ev.clientY);
      city.bldU.uHover.value = bi; canvas.style.cursor = bi >= 0 ? 'pointer' : '';
      hov = { b: bi, s: -1 };
      if (bi >= 0) buildingTip(bi, ev); else hideTip();
    }, 45);
  });
  canvas.addEventListener('pointerleave', () => { clearTimeout(hoverTimer); hideTip(); city.bldU.uHover.value = -1; city.stU.uHoverSt.value = -1; });
  // keep tooltips live when the level changes under a still pointer
  const refreshTip = () => { if (tip.hidden) return; if (hov.s >= 0) stationTip(hov.s); else if (hov.b >= 0) buildingTip(hov.b); };

  function selectStation(i, fly = false) {
    state.selSt = i; city.stU.uSelectedSt.value = i;
    const lab = $('#stSelLabel'); if (lab) lab.remove();
    if (i >= 0) {
      const s = stations[i];
      if (fly) { const cur = city.currentView(); city.flyTo({ x: s.x, z: s.z, dist: Math.min(cur.dist, 900), az: cur.az, polar: cur.polar }, 1600); }
      const d = document.createElement('div'); d.className = 'lbl'; d.id = 'stSelLabel'; d.innerHTML = `<span class="lb stlabel">${s.name} ${badges(s)}</span>`;
      $('#labels').appendChild(d); d._st = s;
      if (state.stationsOpen) $$('#stUl li').forEach((li) => li.classList.toggle('sel', +li.dataset.i === i));
    }
  }

  // -------------------------------------------------------------------------- station list
  function buildStationList() {
    const ul = $('#stUl'); ul.innerHTML = '';
    const q = $('#stSearch').value.trim().toLowerCase();
