    if (e.target === slider) { if (e.key === ' ') e.preventDefault(); else if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'PageUp', 'PageDown'].includes(e.key)) { anim = null; stopPlay(); return; } }
    const step = e.shiftKey ? 10 : 1; let handled = true;
