    if (handled && e.target === slider) e.preventDefault();
  });

  // -------------------------------------------------------------------------- init
  buildTicks(); buildDepthRamp();
  const h0 = readHash();
  if (h0.lang) { setLang(h0.lang); $$('#langSeg button').forEach((x) => x.classList.toggle('on', x.dataset.lang === getLang())); }
  if (h0.theme && h0.theme !== state.theme) setTheme(h0.theme);
  if (h0.mode) { state.mode = 1; city.setMode(1); $$('#modeSeg button').forEach((x) => x.classList.toggle('on', +x.dataset.mode === 1)); }
  drawArea(); applyI18n();
  if (h0.level != null) setLevel(h0.level);
  city.on('frame', () => { updateLabels(); });
  setInterval(refreshTip, 200);
  requestAnimationFrame(tick);
  return { state, setLevel, animateTo, setMode, setTheme, selectStation, VIEWS };
}

import { HISTORIC, MAX_LEVEL, lineColor, MODE_LABEL, DEPTH_RAMP, DEPTH_STOPS, Y_REF } from './config.js';
