    if (!fromSlider) slider.value = Math.round(state.level * 100);
    slider.style.setProperty('--v', state.level / MAX_LEVEL);
    if (!rafPending) { rafPending = true; requestAnimationFrame(() => { rafPending = false; update(); }); }
  }
  let anim = null;
  function animateTo(target, ms = 1600) {
    stopPlay();
