    if (k >= 1) anim = null;
  }
  slider.addEventListener('input', () => { anim = null; stopPlay(); setLevel(slider.value / 100, true); });
  $$('.steppers button').forEach((b) => b.addEventListener('click', () => { anim = null; stopPlay(); setLevel(Math.round(state.level * 100 + +b.dataset.step) / 100); }));

  // playback with a short pause on each historic level
  let linger = 0, lastCross = -1;
  function startPlay() {
    if (state.level >= MAX_LEVEL - 0.005) setLevel(0);
    state.playing = true; lastCross = state.level; $('#playLabel').textContent = t('pause');
    $('#playIcon').setAttribute('d', 'M6 4h4v16H6zM14 4h4v16h-4z');
  }
  function stopPlay() { state.playing = false; $('#playLabel').textContent = t('play'); $('#playIcon').setAttribute('d', 'M7 4.5v15l12-7.5z'); }
  $('#playBtn').onclick = () => (state.playing ? stopPlay() : (anim = null, startPlay()));
  $('#resetBtn').onclick = () => { stopPlay(); animateTo(0, 1200); };
  $$('#speedSeg button').forEach((b) => (b.onclick = () => { state.speed = +b.dataset.speed; $$('#speedSeg button').forEach((x) => x.classList.toggle('on', x === b)); }));

  function toast(msg) {
    const el = $('#toast'); el.textContent = msg; el.classList.add('show');
    clearTimeout(toast.t); toast.t = setTimeout(() => el.classList.remove('show'), 2300);
  }
  let lastT = performance.now();
  function tick(now) {
    const dt = Math.min(0.1, (now - lastT) / 1000); lastT = now;
    stepAnim(now);
    if (state.playing) {
