        const next = Math.min(MAX_LEVEL, prev + state.speed * dt);
        const hit = HISTORIC.find((h) => prev < h.level && next >= h.level);
        if (hit) { setLevel(hit.level); linger = 1.6; toast(`${t('levelToastLabel')} · ${hit.year} · +${nf(hit.level, 2)} m`); }
        else setLevel(next);
        if (next >= MAX_LEVEL) stopPlay();
      }
    }
    requestAnimationFrame(tick);
  }

  // -------------------------------------------------------------------------- statistics
  const totalB = data.buildings.geom.n;
  const landHa = meta.counts.landHa;
  const stModes = ['METRO', 'RER', 'TRAIN', 'TRAMWAY'];
  const stTotals = Object.fromEntries(stModes.map((m) => [m, stations.filter((s) => s.modes.includes(m)).length]));
  const thr = (s) => (state.mode ? s.tl : s.tc) / 100;
  const arrTotals = new Array(21).fill(0);
  { const arr = data.buildings.attr.arr; for (let i = 0; i < arr.length; i++) arrTotals[arr[i]]++; }
  const arrMax = [0, 1].map((m) => { let mx = 1; for (let a = 1; a <= 20; a++) mx = Math.max(mx, stats.buildings[(m * 21 + a) * NL + 1000]); return mx; });

  function stationCounts(L) {
    const c = { flooded: 0, alert: 0, byMode: { METRO: 0, RER: 0, TRAIN: 0, TRAMWAY: 0 } };
    for (const s of stations) {
      const m = thr(s) - L;
      if (m <= 0.0005) { c.flooded++; for (const md of s.modes) if (md in c.byMode) c.byMode[md]++; } else if (m <= 0.5) c.alert++;
    }
    return c;
  }
  const dmaxAt = (L) => {
