    const next = HISTORIC.find((h) => h.level > L + 0.005);
    let cmp;
    if (L < 0.02) cmp = t('normal');
    else if (near) cmp = t('cmpEqual')(near.year);
    else if (next) cmp = t('cmpNext')(nf(next.level - L, 2), next.year, nf(next.level, 2));
    else cmp = t('cmpBeyond1910')(nf(L - 8.62, 2));
    const cEl = $('#compare'); cEl.textContent = cmp; cEl.classList.toggle('hot', L >= 5.84);
    $$('.marker').forEach((mk) => mk.classList.toggle('active', Math.abs(+mk.dataset.level - L) < 0.005));
    $('#pinLevel') && ($('#pinLevel').textContent = `+${fmtL(L)} m`);
    // counters
    const ha = stats.area[(m * 3) * NL + idx];
    el.area.textContent = nf(ha, ha >= 100 ? 0 : 1);
    el.sArea.textContent = ha < 0.05 ? t('areaNote') : t('areaShare')(nf((ha / landHa) * 100, 1));
    const nb = stats.buildings[(m * 21) * NL + idx];
    el.bld.textContent = nf(nb);
    el.sBld.textContent = t('buildingsShare')(nf((nb / totalB) * 100, 1), nf(totalB));
    const sc = stationCounts(L);
    el.st.textContent = sc.flooded;
    el.sSt.textContent = `${t('stationsOf')(stations.length)}${sc.alert ? ' · ' + sc.alert + ' ' + t('stateAlert').toLowerCase() : ''}`;
    el.pills.innerHTML = stModes.map((md) => `<span class="pill ${sc.byMode[md] ? 'hot' : ''}">${MODE_LABEL[md]} ${sc.byMode[md]}/${stTotals[md]}</span>`).join('');
    const dm = dmaxAt(L);
    el.depth.textContent = nf(dm, 1);
    el.sDepth.textContent = dm < 0.05 ? '—' : `≈ ${nf(dm / 3.1, 1)} ${getLang() === 'fr' ? 'étages' : 'storeys'}`;
