  // -------------------------------------------------------------------------- arrondissement chart
  const arrRows = [];
  function buildArrChart() {
    const box = $('#arrChart'); box.innerHTML = ''; arrRows.length = 0;
    for (let a = 1; a <= 20; a++) {
      const r = document.createElement('div'); r.className = 'arr-row';
      r.innerHTML = `<span class="n">${t('arrLabel')(a)}</span><span class="bar"><i></i></span><span class="v">0</span>`;
      r.addEventListener('pointerenter', (e) => showArrTip(a, e)); r.addEventListener('pointermove', moveTip); r.addEventListener('pointerleave', hideTip);
      r.addEventListener('click', () => { const am = meta.arrondissements[a - 1]; city.flyTo({ x: am.x, z: am.z, dist: 3400, az: 0.2, polar: 1.05 }, 2200); });
      box.appendChild(r); arrRows.push(r);
    }
  }
  function arrStats(a, idx) {
