  }
  function buildArrTable(idx) {
    let h = `<table><thead><tr><th>${t('arrCol')}</th><th>${t('bldCol')}</th><th>${t('shareCol')}</th><th>${t('areaCol')}</th></tr></thead><tbody>`;
    for (let a = 1; a <= 20; a++) { const s = arrStats(a, idx); h += `<tr><td>${t('arrLabel')(a)}</td><td>${nf(s.b)}</td><td>${nf((s.b / s.tot) * 100, 1)} %</td><td>${nf(s.ha, 1)}</td></tr>`; }
    $('#arrTable').innerHTML = h + '</tbody></table>';
  }
  $('#chartToggle').onclick = () => {
    state.chartTable = !state.chartTable;
    $('#arrChart').hidden = state.chartTable; $('#arrTable').hidden = !state.chartTable;
    $('#chartToggle').textContent = state.chartTable ? t('chartView') : t('tableView'); update();
  };

  // -------------------------------------------------------------------------- tooltip
  const tip = $('#tooltip');
  let tipPos = { x: 0, y: 0 };
  function placeTip() {
    const w = tip.offsetWidth, h = tip.offsetHeight;
    let x = tipPos.x + 16, y = tipPos.y + 16;
    if (x + w > innerWidth - 8) x = tipPos.x - w - 16;
    if (y + h > innerHeight - 8) y = tipPos.y - h - 16;
    tip.style.left = Math.max(8, x) + 'px'; tip.style.top = Math.max(8, y) + 'px';
  }
  function moveTip(e) { tipPos = { x: e.clientX, y: e.clientY }; placeTip(); }
  function hideTip() { tip.hidden = true; }
  function showTip(html, e) { tip.innerHTML = html; tip.hidden = false; if (e) tipPos = { x: e.clientX, y: e.clientY }; placeTip(); }
  function showArrTip(a, e) {
    const idx = clamp(Math.round(state.level * 100), 0, 1000), s = arrStats(a, idx);
    showTip(`<div class="t-title">${t('arrLabel')(a)} ${t('arrSuffix')}</div><dl><dt>${t('bldCol')}</dt><dd>${nf(s.b)} / ${nf(s.tot)} (${nf((s.b / s.tot) * 100, 0)}%)</dd><dt>${t('areaCol')}</dt><dd>${nf(s.ha, 1)}</dd></dl>`, e);
  }

  function badges(s) {
    const out = [];
    for (const [mode, label] of s.lines) {
      if (mode === 'TRAIN') continue;
      const c = lineColor(mode, label);
      const lum = (parseInt(c.slice(1, 3), 16) * 0.299 + parseInt(c.slice(3, 5), 16) * 0.587 + parseInt(c.slice(5, 7), 16) * 0.114);
      out.push(`<span class="badge ${mode === 'METRO' ? '' : 'sq'}" style="background:${c};color:${lum > 150 ? '#111' : '#fff'}">${mode === 'RER' ? 'RER ' : ''}${label}</span>`);
    }
    if (s.modes.includes('TRAIN')) out.push(`<span class="badge sq" style="background:#8a8f98;color:#fff">${MODE_LABEL.TRAIN}</span>`);
    return `<span class="badges">${out.join('')}</span>`;
  }
  const stateOf = (s) => { const m = thr(s) - state.level; return m <= 0.0005 ? 'flooded' : m <= 0.5 ? 'alert' : 'ok'; };
  function stationTip(i, e) {
    const s = stations[i], st = stateOf(s), T = t('hoverStation'), th = thr(s);
    showTip(`<div class="t-title">${s.name} ${badges(s)}</div><dl><dt>${T.ground}</dt><dd>${nf(s.ngf, 2)} m NGF</dd><dt>${T.from}</dt><dd>${th >= 25 ? '—' : '+' + nf(th, 2) + ' m'}</dd></dl>
      <div class="state ${st}">${st === 'flooded' ? t('stateFlooded') : st === 'alert' ? t('stateAlert') : t('stateOk')}</div>`, e);
  }
  const bStart = (() => { // first vertex of each building, to locate it
    const g = data.buildings.geom; const rs = new Uint32Array(g.n + 1), vs = new Uint32Array(g.n + 1);
    let r = 0, v = 0;
    for (let b = 0; b < g.n; b++) { rs[b] = r; vs[b] = v; for (let k = 0; k < g.ringCount[b]; k++) v += g.ringLen[r + k]; r += g.ringCount[b]; }
    return { rs, vs };
  })();
  function buildingCenter(i) {
    const g = data.buildings.geom, v0 = bStart.vs[i], n = g.ringLen[bStart.rs[i]];
    let sx = 0, sz = 0;
    for (let k = 0; k < n; k++) { sx += (g.origin[2 * i] + g.xy[2 * (v0 + k)]) / 10; sz += -(g.origin[2 * i + 1] + g.xy[2 * (v0 + k) + 1]) / 10; }
    return { x: sx / n, z: sz / n };
  }
  function buildingTip(i, e) {
    const a = data.buildings.attr, T = t('hoverBuilding');
    const th = (state.mode ? a.tl[i] : a.tc[i]) / 100;
    const s = (state.mode ? a.tl[i] : a.tc[i]) / 100;
    const surf = meta.hydro.gaugeZeroNgf + state.level - slopeK(state.level) * a.s[i];
    const wet = th <= state.level + 0.0005;
    const depth = wet ? Math.max(0, surf - a.z[i]) : 0;
    const arr = a.arr[i];
    showTip(`<div class="t-title">${T.title} · ${t('arrLabel')(arr)} ${t('arrSuffix')}</div>
      <dl>${a.year[i] > 1000 ? `<dt>${T.built}</dt><dd>${a.year[i]}</dd>` : ''}<dt>${T.height}</dt><dd>${nf(a.h[i], 0)} m</dd><dt>${T.ground}</dt><dd>${nf(a.z[i], 1)} m NGF</dd>
      <dt>${T.floodsFrom}</dt><dd>${s >= 25 ? T.never : '+' + nf(s, 2) + ' m'}</dd></dl>
      <div class="state ${wet ? 'flooded' : 'ok'}">${wet ? `${T.depthNow} : ${nf(depth, 2)} m` : T.dry}</div>`, e);
  }
  function slopeK(L) { const h = meta.hydro; const x = clamp((L - h.slopeL0) / (h.slopeL1 - h.slopeL0), 0, 1); return h.slopeKm * x * x * (3 - 2 * x); }

  // -------------------------------------------------------------------------- pointer interaction on the map
  const canvas = city.canvas;
  let down = null, hoverTimer = 0, hov = { b: -1, s: -1 };
  canvas.addEventListener('pointerdown', (e) => { down = { x: e.clientX, y: e.clientY, t: performance.now() }; hideTip(); });
  canvas.addEventListener('pointerup', (e) => {
    if (!down) return;
    const moved = Math.hypot(e.clientX - down.x, e.clientY - down.y); down = null;
    if (moved > 5 || e.button !== 0) return;
    const si = city.pickStation(e.clientX, e.clientY);
    if (si >= 0) { selectStation(si, true); return; }
    const bi = city.pickBuilding(e.clientX, e.clientY);
    if (bi >= 0) { state.selB = bi; city.bldU.uSelected.value = bi; const c = buildingCenter(bi); const cur = city.currentView(); city.flyTo({ x: c.x, z: c.z, dist: Math.min(cur.dist, 700), az: cur.az, polar: cur.polar }, 1400); }
    else { state.selB = -1; city.bldU.uSelected.value = -1; selectStation(-1); }
  });
  canvas.addEventListener('pointermove', (e) => {
    if (e.buttons) { hideTip(); return; }
    const ev = { clientX: e.clientX, clientY: e.clientY };
    clearTimeout(hoverTimer);
    hoverTimer = setTimeout(() => {
      const si = city.pickStation(ev.clientX, ev.clientY);
      if (si >= 0) {
        city.stU.uHoverSt.value = si; city.bldU.uHover.value = -1; canvas.style.cursor = 'pointer'; stationTip(si, ev); hov = { b: -1, s: si }; return;
      }
      city.stU.uHoverSt.value = -1;
      const bi = city.pickBuilding(ev.clientX, ev.clientY);
      city.bldU.uHover.value = bi; canvas.style.cursor = bi >= 0 ? 'pointer' : '';
      hov = { b: bi, s: -1 };
      if (bi >= 0) buildingTip(bi, ev); else hideTip();
    }, 45);
  });
  canvas.addEventListener('pointerleave', () => { clearTimeout(hoverTimer); hideTip(); city.bldU.uHover.value = -1; city.stU.uHoverSt.value = -1; });
  // keep tooltips live when the level changes under a still pointer
  const refreshTip = () => { if (tip.hidden) return; if (hov.s >= 0) stationTip(hov.s); else if (hov.b >= 0) buildingTip(hov.b); };

  function selectStation(i, fly = false) {
    state.selSt = i; city.stU.uSelectedSt.value = i;
    const lab = $('#stSelLabel'); if (lab) lab.remove();
    if (i >= 0) {
      const s = stations[i];
      if (fly) { const cur = city.currentView(); city.flyTo({ x: s.x, z: s.z, dist: Math.min(cur.dist, 900), az: cur.az, polar: cur.polar }, 1600); }
      const d = document.createElement('div'); d.className = 'lbl'; d.id = 'stSelLabel'; d.innerHTML = `<span class="lb stlabel">${s.name} ${badges(s)}</span>`;
      $('#labels').appendChild(d); d._st = s;
      if (state.stationsOpen) $$('#stUl li').forEach((li) => li.classList.toggle('sel', +li.dataset.i === i));
    }
  }

  // -------------------------------------------------------------------------- station list
  function buildStationList() {
    const ul = $('#stUl'); ul.innerHTML = '';
    const q = $('#stSearch').value.trim().toLowerCase();
    const order = stations.map((s, i) => i).sort((a, b) => thr(stations[a]) - thr(stations[b]));
    for (const i of order) {
      const s = stations[i]; if (q && !s.name.toLowerCase().includes(q)) continue;
      const li = document.createElement('li'); li.dataset.i = i;
      const th = thr(s);
      li.innerHTML = `<span class="dot"></span><span class="nm">${s.name}</span>${badges(s)}<span class="lv">${th >= 25 ? '—' : '+' + nf(th, 2)}</span>`;
      li.onclick = () => selectStation(i, true);
      ul.appendChild(li);
    }
    updateStationList();
  }
  function updateStationList() {
    for (const li of $$('#stUl li')) { const st = stateOf(stations[+li.dataset.i]); li.className = st === 'ok' ? '' : st; }
  }
  $('#stationsTile').onclick = () => {
    state.stationsOpen = !state.stationsOpen; $('#stationsTile').setAttribute('aria-expanded', state.stationsOpen);
    $('#stationsList').hidden = !state.stationsOpen; if (state.stationsOpen) buildStationList();
  };
  $('#stSearch').addEventListener('input', buildStationList);

  // -------------------------------------------------------------------------- layers & options
  $('#lyBuildings').onchange = (e) => city.setBuildingsVisible(e.target.checked);
  $('#lyStations').onchange = (e) => city.setStations(e.target.checked);
  $('#lyArr').onchange = (e) => city.setArrLines(e.target.checked);
  $('#lyContours').onchange = (e) => city.setContours(e.target.checked);
  $('#lyLabels').onchange = (e) => { state.labels = e.target.checked; $('#labels').style.display = e.target.checked ? '' : 'none'; };
  $('#lyPPRI').onchange = async (e) => {
    const on = e.target.checked; $('#ppriLegend').hidden = !on;
    if (on && !state.ppriLoaded) {
      const { loadPPRI } = await import('./data.js');
      await city.enablePPRI(await loadPPRI()); state.ppriLoaded = true;
    }
    city.setPPRI(on);
  };
  $('#ppriOpacity').oninput = (e) => { if (city.ppriU) city.ppriU.uOpacity.value = e.target.value / 100; };
  $$('#modeSeg button').forEach((b) => (b.onclick = () => setMode(+b.dataset.mode)));
  function setMode(m) {
    state.mode = m; city.setMode(m);
    $$('#modeSeg button').forEach((x) => x.classList.toggle('on', +x.dataset.mode === m));
    $('#modeHint').textContent = m ? t('modeAnyHint') : t('modeConnectedHint');
    drawArea(); buildStationList(); update();
  }
  $('#exag').oninput = (e) => { const v = e.target.value / 10; city.setExag(v); $('#exagOut').textContent = '×' + v.toFixed(1).replace('.0', ''); };
  $$('#themeSeg button').forEach((b) => (b.onclick = () => setTheme(b.dataset.theme)));
  function setTheme(n) { state.theme = n; city.setTheme(n); $$('#themeSeg button').forEach((x) => x.classList.toggle('on', x.dataset.theme === n)); buildDepthRamp(); }
  $$('#langSeg button').forEach((b) => (b.onclick = () => { setLang(b.dataset.lang); $$('#langSeg button').forEach((x) => x.classList.toggle('on', x === b)); applyI18n(); }));
  $('#aboutBtn').onclick = () => ($('#aboutModal').hidden = false);
  $('#aboutClose').onclick = () => ($('#aboutModal').hidden = true);
  $('#aboutModal').addEventListener('click', (e) => { if (e.target.id === 'aboutModal') $('#aboutModal').hidden = true; });
  $$('.panel-toggle').forEach((b) => (b.onclick = () => $('#' + b.dataset.toggle).classList.toggle('collapsed')));
  if (innerWidth < 1100) $$('.panel').forEach((p) => p.classList.add('collapsed'));

  function buildDepthRamp() {
    const stops = DEPTH_RAMP.map((c, i) => `${c} ${(DEPTH_STOPS[i] / 7) * 100}%`).join(', ');
    $('#depthRamp').style.background = `linear-gradient(90deg, ${stops})`;
  }

  // -------------------------------------------------------------------------- labels
  const labelRoot = $('#labels');
  let labels = [];
  function rebuildLabels() {
    labelRoot.innerHTML = ''; labels = [];
    const add = (cls, html, x, z, prio, minD, maxD, dy = 0) => {
      const d = document.createElement('div'); d.className = 'lbl'; d.innerHTML = `<span class="lb ${cls}">${html}</span>`;
      labelRoot.appendChild(d); labels.push({ d, x, z, prio, minD, maxD, dy, cls, w: 0, h: 0 });
    };
    for (const l of meta.landmarks) {
      const prio = { landmark: 5, station: 4, island: 6, park: 2, edge: 1 }[l.kind] || 3;
      add(l.kind === 'station' ? 'landmark' : l.kind, l.name, l.x, l.z, prio, 0, l.kind === 'edge' ? 30000 : 9500, 40);
    }
    for (const a of meta.arrondissements) add('arr', t('arrLabel')(a.n).replace(/(\D+)$/, '<small>$1</small>'), a.x, a.z, 0, 3200, 30000, 0);
    const pin = document.createElement('div'); pin.className = 'lbl';
    pin.innerHTML = `<span class="lb gaugepin"><i></i><span>Austerlitz</span><b id="pinLevel">+${fmtL(state.level)} m</b></span>`;
    labelRoot.appendChild(pin); labels.push({ d: pin, x: meta.gauge.x, z: meta.gauge.z, prio: 10, minD: 0, maxD: 60000, dy: 20, cls: 'gaugepin', w: 0, h: 0 });
  }
  const vv = { };
  function updateLabels() {
    if (!state.labels) return;
    const dist = city.camera.position.distanceTo(city.controls.target);
    const placed = [];
    const sorted = labels.slice().sort((a, b) => b.prio - a.prio);
    for (const L of sorted) {
      let vis = dist >= L.minD && dist <= L.maxD;
      let p = null;
      if (vis) {
        p = city.project(L.x, city.groundY(L.x, L.z) + L.dy * (city.exag || 1), L.z);
        vis = p.visible && p.x > -40 && p.x < city.w + 40 && p.y > -20 && p.y < city.h + 20;
      }
      if (vis && L.cls !== 'arr') {
        if (!L.w) { const r = L.d.firstChild.getBoundingClientRect(); L.w = r.width || 80; L.h = r.height || 16; }
        const box = [p.x - 6, p.y - L.h / 2 - 3, p.x + L.w + 6, p.y + L.h / 2 + 3];
        if (placed.some((b) => !(box[2] < b[0] || box[0] > b[2] || box[3] < b[1] || box[1] > b[3]))) vis = false; else placed.push(box);
      }
      if (vis) { L.d.style.transform = `translate(${p.x.toFixed(1)}px, ${p.y.toFixed(1)}px)`; if (L.hid) { L.d.style.display = ''; L.hid = false; } }
      else if (!L.hid) { L.d.style.display = 'none'; L.hid = true; }
    }
    const sel = $('#stSelLabel');
    if (sel && sel._st) {
      const s = sel._st; const p = city.project(s.x, (s.ngf - Y_REF) * (city.exag || 1) + 70, s.z);
      sel.style.transform = `translate(${p.x.toFixed(1)}px, ${p.y.toFixed(1)}px)`; sel.style.display = p.visible ? '' : 'none';
    }
  }

  // -------------------------------------------------------------------------- URL state
  let hashT = 0;
  function scheduleHash() { clearTimeout(hashT); hashT = setTimeout(() => { history.replaceState(null, '', `#l=${state.level.toFixed(2)}&m=${state.mode}&t=${state.theme}&lang=${getLang()}`); }, 400); }
  function readHash() {
    const p = new URLSearchParams(location.hash.slice(1)); const o = {};
    if (p.has('l')) o.level = clamp(+p.get('l') || 0, 0, MAX_LEVEL);
    if (p.has('m')) o.mode = +p.get('m') ? 1 : 0;
    if (p.has('t') && (p.get('t') === 'day' || p.get('t') === 'night')) o.theme = p.get('t');
    if (p.has('lang')) o.lang = p.get('lang');
    return o;
  }

  // -------------------------------------------------------------------------- keyboard
  window.addEventListener('keydown', (e) => {
    if (/INPUT|SELECT|TEXTAREA/.test(e.target.tagName) && e.target.type !== 'range') return;
    if (e.target === slider) { if (e.key === ' ') e.preventDefault(); else if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'PageUp', 'PageDown'].includes(e.key)) { anim = null; stopPlay(); return; } }
    const step = e.shiftKey ? 10 : 1; let handled = true;
    switch (e.key) {
      case 'ArrowRight': case 'ArrowUp': anim = null; setLevel((Math.round(state.level * 100) + step) / 100); break;
      case 'ArrowLeft': case 'ArrowDown': anim = null; setLevel((Math.round(state.level * 100) - step) / 100); break;
      case 'PageUp': setLevel(Math.round(state.level) + 1); break;
      case 'PageDown': setLevel(Math.round(state.level) - 1); break;
      case ' ': state.playing ? stopPlay() : startPlay(); break;
      case 'Escape': $('#aboutModal').hidden = true; selectStation(-1); break;
      default: handled = false;
    }
    if (handled && e.target !== slider) e.preventDefault();
    if (handled && e.target === slider) e.preventDefault();
  });

  // -------------------------------------------------------------------------- init
  buildTicks(); buildDepthRamp();
  const h0 = readHash();
  if (h0.lang) { setLang(h0.lang); $$('#langSeg button').forEach((x) => x.classList.toggle('on', x.dataset.lang === getLang())); }
  if (h0.theme && h0.theme !== state.theme) setTheme(h0.theme);
  if (h0.mode) { state.mode = 1; city.setMode(1); $$('#modeSeg button').forEach((x) => x.classList.toggle('on', +x.dataset.mode === 1)); }
  drawArea(); applyI18n();
  if (h0.level != null) setLevel(h0.level);
  city.on('frame', () => { updateLabels(); });
  setInterval(refreshTip, 200);
  requestAnimationFrame(tick);
  return { state, setLevel, animateTo, setMode, setTheme, selectStation, VIEWS };
}

