import { HISTORIC, MAX_LEVEL, lineColor, MODE_LABEL, DEPTH_RAMP, DEPTH_STOPS, Y_REF } from './config.js';
import { t, nf, setLang, getLang } from './i18n.js';

const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const fmtL = (v) => v.toFixed(2);

const VIEWS = [
  { key: 'overview', en: 'Overview', fr: "Vue d'ensemble", view: { x: 250, z: 500, dist: 10800, az: 0.22, polar: 1.0 } },
  { key: 'cite', en: 'Île de la Cité', fr: 'Île de la Cité', view: { x: 760, z: 420, dist: 1500, az: -0.55, polar: 1.12 } },
  { key: 'austerlitz', en: 'Austerlitz · Gare de Lyon', fr: 'Austerlitz · Gare de Lyon', view: { x: 2650, z: 1750, dist: 2500, az: -0.75, polar: 1.1 } },
  { key: 'concorde', en: 'Concorde · Orsay', fr: 'Concorde · Orsay', view: { x: -800, z: -250, dist: 2100, az: 0.55, polar: 1.1 } },
  { key: 'eiffel', en: 'Tour Eiffel · Grenelle', fr: 'Tour Eiffel · Grenelle', view: { x: -3300, z: 650, dist: 2900, az: 0.9, polar: 1.05 } },
  { key: 'javel', en: 'Javel · Auteuil', fr: 'Javel · Auteuil', view: { x: -5000, z: 1450, dist: 3400, az: 0.95, polar: 1.0 } },
];

export function initUI(city, data, opts = {}) {
  const meta = data.meta, stats = data.stats, NL = meta.nl;
  const stations = data.stations;
  const state = { level: 0, mode: 0, playing: false, speed: 0.6, theme: city.themeName, selSt: -1, selB: -1, chartTable: false, stationsOpen: false, labels: true, ppriLoaded: false };

  // -------------------------------------------------------------------------- i18n
  function applyI18n() {
    $$('[data-i]').forEach((el) => { const v = t(el.dataset.i); if (typeof v === 'string') el.textContent = v; });
    $$('[data-iph]').forEach((el) => { el.placeholder = t(el.dataset.iph); });
    $('#aboutBody').innerHTML = t('aboutBody');
    $('#aboutCredits').textContent = t('credits');
    $('#credits').textContent = t('credits');
    $('#slider').setAttribute('aria-label', t('levelAria'));
    $('#modeHint').textContent = state.mode ? t('modeAnyHint') : t('modeConnectedHint');
    $('#chartToggle').textContent = state.chartTable ? t('chartView') : t('tableView');
    $('#playLabel').textContent = state.playing ? t('pause') : t('play');
    $('#resetBtn').textContent = t('reset');
    $('#modeSeg [data-mode="0"]').textContent = t('modeConnected'); $('#modeSeg [data-mode="1"]').textContent = t('modeAny');
    buildViewChips(); buildMarkers(); buildStationList(); rebuildLabels(); buildArrChart(); update(true);
  }

  // -------------------------------------------------------------------------- viewpoints
  function buildViewChips() {
    const box = $('#viewChips'); box.innerHTML = '';
    for (const v of VIEWS) {
      const b = document.createElement('button'); b.textContent = v[getLang()];
      b.onclick = () => city.flyTo(v.view, 2600);
      box.appendChild(b);
    }
  }

  // -------------------------------------------------------------------------- gauge
  const slider = $('#slider'), track = $('#track');
  function buildTicks() {
    const box = $('#ticks'); box.innerHTML = '';
    for (let i = 0; i <= MAX_LEVEL; i++) { const s = document.createElement('span'); s.style.left = (i / MAX_LEVEL) * 100 + '%'; s.textContent = i; box.appendChild(s); }
  }
  function buildMarkers() {
    const box = $('#markers'); box.innerHTML = '';
    const side = { 2018: 'l', 2016: 'r', 1955: 'c', 1910: 'c' };
    for (const h of HISTORIC) {
      const m = document.createElement('div'); m.className = 'marker ' + side[h.year]; m.dataset.level = h.level;
      m.style.left = (h.level / MAX_LEVEL) * 100 + '%';
      const b = document.createElement('button');
      b.innerHTML = `<b>${h.year}</b>${nf(h.level, 2)}`;
      b.title = t('markerTitle')(h.year, nf(h.level, 2));
      b.onclick = () => animateTo(h.level, 1800);
      m.appendChild(b); box.appendChild(m);
    }
  }
  function drawArea() {
    const svg = $('#areaSvg'); const mode = state.mode;
    const base = mode * 3 * NL; const max = stats.area[base + 1000] || 1;
    let d = 'M0 40';
    for (let c = 0; c <= 1000; c += 5) d += ` L${c} ${(40 - (stats.area[base + c] / max) * 38).toFixed(2)}`;
    d += ' L1000 40 Z';
    svg.setAttribute('viewBox', '0 0 1000 40');
    svg.innerHTML = `<defs><linearGradient id="ag" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".55"/><stop offset="1" stop-color="var(--accent)" stop-opacity=".04"/></linearGradient>
      <clipPath id="clipL"><rect id="clipRect" x="0" y="-2" width="0" height="44"/></clipPath></defs>
