import { createRequire } from 'module';
const require = createRequire('/usr/local/lib/node_modules/');
const { chromium } = require('playwright');
const b = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const p = await b.newPage({ viewport: { width: 1440, height: 900 } });
const errs = [];
p.on('pageerror', (e) => { errs.push(e.message); console.log('[pageerror]', e.message.slice(0, 500)); });
p.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') console.log(`[${m.type()}]`, m.text().slice(0, 300)); });
await p.goto('http://127.0.0.1:5173/?manual=1&dpr=1#l=7.12');
await p.waitForFunction(() => window.__ready === true, null, { timeout: 240000 });
const shot = async (name) => { await p.evaluate(() => { window.city.render(); window.city.render(); }); await p.waitForTimeout(400); await p.screenshot({ path: `/tmp/probe/${name}.png` }); };

// 1. hover a building near the Gare d'Austerlitz area
await p.evaluate(() => window.city.setView({ x: 2500, z: 1750, dist: 900, az: -0.7, polar: 1.1 }));
await p.evaluate(() => window.city.render());
await p.mouse.move(700, 330);
await p.mouse.move(702, 332);
await p.waitForTimeout(700);
await shot('e2e_hover');
console.log('tooltip:', await p.evaluate(() => document.getElementById('tooltip').hidden ? 'hidden' : document.getElementById('tooltip').innerText.replace(/\n/g, ' | ')));

// 2. station list + FR + table view
await p.click('#stationsTile');
await p.click('#chartToggle');
await p.click('#langSeg [data-lang="fr"]');
await p.waitForTimeout(300);
await p.evaluate(() => window.ui.setLevel(8.62));
await shot('e2e_fr');

