await p.click('#chartToggle');
await p.click('#stationsTile');
await p.click('#modeSeg [data-mode="1"]');
await p.click('#lyPPRI');
await p.waitForTimeout(1500);
await p.evaluate(() => window.city.setView({ x: -2600, z: 900, dist: 2600, az: 0.5, polar: 1.1 }));
await shot('e2e_ppri');
console.log('errors:', errs.length);
await b.close();

