root = '/workspace/'
def edit(path, pairs):
    s = open(root + path).read()
    for a, b in pairs:
        if a not in s:
            raise SystemExit(f'pattern not found in {path}: {a[:60]!r}')
        s = s.replace(a, b, 1)
    open(root + path, 'w').write(s)

# ---------------------------------------------------------------- shaders
s = open(root + 'src/gl/shaders.js').read()
s += r'''
// ----------------------------------------------------------------------------------- bridge decks (schematic)
export const bridgeVS = /* glsl */ `
${COMMON}
attribute vec3 aInfo;     // x = across-deck coordinate (-1..1), y = part (0 top, 1 wall top, 2 wall bottom), z = kind (0 road, 1 foot, 2 rail)
varying vec3 vWorld;
varying vec3 vInfo;
varying float vNGF;
varying float vSurf;
void main() {
  vec2 xz = position.xz;
  float s = riverSAt(xzToUV(xz));
  vSurf = surfaceZ(uLevel, s);
  vNGF = position.y;
  vInfo = aInfo;
  vec3 p = vec3(xz.x, sceneY(position.y), xz.y);
  vWorld = p;
  gl_Position = projectionMatrix * viewMatrix * vec4(p, 1.0);
}`;
export const bridgeFS = /* glsl */ `
${COMMON}
uniform vec3 uDeckRoad; uniform vec3 uDeckFoot; uniform vec3 uDeckRail; uniform vec3 uDeckStone; uniform vec3 uWaterTint;
varying vec3 vWorld;
varying vec3 vInfo;
varying float vNGF;
varying float vSurf;
void main() {
  vec3 dx = dFdx(vWorld), dy = dFdy(vWorld);
  vec3 n = normalize(cross(dx, dy));
  vec3 V = normalize(cameraPosition - vWorld);
  if (dot(n, V) < 0.0) n = -n;
  bool top = vInfo.y < 0.5;
  vec3 deck = vInfo.z > 1.5 ? uDeckRail : (vInfo.z > 0.5 ? uDeckFoot : uDeckRoad);
  float curb = smoothstep(0.80, 0.88, abs(vInfo.x));
  vec3 base = top ? mix(deck, uDeckStone, curb) : uDeckStone * (0.80 + 0.2 * smoothstep(0.0, 1.0, vInfo.y - 1.0));
  float ndl = max(dot(n, normalize(uSunDir)), 0.0);
  float sh = ndl > 0.0 ? shadowAt(vWorld + n * 0.3, ndl) : 1.0;
  vec3 hemi = mix(uAmbGround, uAmbSky, n.y * 0.5 + 0.5);
  vec3 c = base * (hemi * uAmbient + uSunCol * ndl * sh);
  float under = 1.0 - smoothstep(vSurf - 0.05, vSurf + 0.05, vNGF);
  c = mix(c, uWaterTint * 0.9, under * 0.8);
  float line = exp(-pow((vNGF - vSurf) / 0.18, 2.0));
  c += vec3(0.55, 0.95, 1.0) * line * 0.7;
  c = applyFog(c, distance(cameraPosition, vWorld));
  gl_FragColor = vec4(toDisplay(c), 1.0);
}`;
'''
